insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('linesizing', 'advanced', 'module', 'm01-the-wall-a-code-demands', 1, 'B31.4 and B31.8 Class 1 both hand the SOKU pipe a design factor of 0.720000 and both land on a pressure wall of 0.204327 in. Why is that agreement no reason to size a B31.8 route to B31.4?', '["B31.4 applies its flat 0.720000 only where a route survey has already returned an empty classification, so the agreement holds on this pipe and the two codes part company the moment the survey is missing from the package.", "The agreement is an artefact of the 12.750000 in outside diameter this pipe happens to carry, and the two codes return different pressure walls on the published 8.625000 in and 6.625000 in cases where the diameter is smaller.", "The two factors happen to be the same number while the two statements are different: one code has looked at the route and found it empty, and the other has not looked at the route at all.", "B31.4 carries no location classes at all, so a B31.8 line may be sized to B31.4 wherever the route is Class 1 and the resulting wall is legal under either code."]'::jsonb, 2, 'The design factor depends on the code and the class and not on the pipe, which is why the B31.4 row of the SOKU table reproduces the Class 1 row exactly. A class is a property of each stretch of route, so one line can hold several.'),
  ('linesizing', 'advanced', 'module', 'm01-the-wall-a-code-demands', 2, 'On the SOKU pipe at 1200.000000 psig the Class 4 pressure wall of 0.367788 in is 1.800000 times the Class 1 pressure wall of 0.204327 in. What moved between those two rows?', '["Only the design factor, which fell from 0.720000 to 0.400000 because the surroundings filled up, and every other input to Barlow stood still.", "The design pressure, which a Class 4 route raises above the 1200.000000 psig a Class 1 route is sized at, so the thicker wall is the same factor applied to a larger demand.", "The specified minimum yield the code is willing to credit, which falls from 52000.000000 psi at Class 1 to a derated figure at Class 4 in the same way the temperature derate lowers it.", "The corrosion allowance, which rises with the class because a populated route is assumed to corrode faster, and it is the 0.125000 in that separates the two figures."]'::jsonb, 0, 'The fluid, the diameter of 12.750000 in, the yield of 52000.000000 psi and the design pressure are identical on both rows. The route is what moved, and because the factor divides, a falling factor is a thickening wall.'),
  ('linesizing', 'advanced', 'module', 'm01-the-wall-a-code-demands', 3, 'The MAOP column of the SOKU table reads 1200.000000 psig on all five rows, from Class 1 through Class 4 and on the B31.4 row. What does that column establish?', '["That every one of the five walls is adequate for 1200.000000 psig with margin to spare, and the column is the engine reporting the lowest of the five ratings so a reader can see the governing case.", "That the location class raises the rating along with the required wall, so a line rolled to Class 4 may be operated above the 1200.000000 psig a Class 1 line is held to.", "That the four design factors cancel out of the rating, which is why the MAOP is a property of the pipe while the required wall is a property of the code.", "That each required wall was derived from 1200.000000 psig and reading the rating back off it returns the pressure it came from, so a thicker wall here is the same rating bought under a stricter factor."]'::jsonb, 3, 'Sizing and rating are one relation read in opposite directions. The round trip closes on each of the four published cases too, returning 1440.000000, 1000.000000, 1000.000000 and 720.000000 psig.'),
  ('linesizing', 'advanced', 'module', 'm01-the-wall-a-code-demands', 4, 'At Class 3 the SOKU call returns a pressure wall of 0.294231 in and a required wall of 0.419231 in. What is the difference between those two numbers doing?', '["It is the margin the code places between the wall that is calculated and the wall that may be ordered, and it grows with the class in the same way the pressure wall does.", "It is the 0.125000 in corrosion allowance, which holds no pressure on the day the line is commissioned and is what lets the pipe still hold pressure years later.", "It is the part of the wall the temperature derate of 1.000000 has released, so on a line running hot the two figures would be closer together.", "It is the difference between the wall Barlow gives and the nearest wall a mill will roll, which on this pipe is 0.375000 in."]'::jsonb, 1, 'The pressure wall is the steel doing structural work and the required wall is the steel somebody orders. Quoting 0.419231 in as the pressure-carrying wall overstates the pipe by the whole allowance from the first day.'),
  ('linesizing', 'advanced', 'module', 'm01-the-wall-a-code-demands', 5, 'At Class 1 the SOKU pressure wall is 0.340545 in at a joint factor of 0.600000 and 0.204327 in at a joint factor of 1.000000. Why does the lower factor give the thicker wall?', '["The joint factor sits in the denominator beside the design factor, so a factor the code credits less leaves more wall to be added to cover what the seam is not being credited with holding.", "The lower factor is applied to the yield rather than to the wall, so it lowers the 52000.000000 psi the steel is credited with and the wall grows to carry the same pressure at a lower stress.", "A welded seam carries a corrosion allowance of its own that a seamless pipe does not, and at a factor of 0.600000 that extra allowance is what separates the two figures.", "The joint factor multiplies the design pressure, so a factor of 0.600000 asks the wall to hold a proportionally higher pressure than the 1200.000000 psig the design stated."]'::jsonb, 0, 'The temperature derate column runs the same way for the same reason: 0.235671 in at a derate of 0.867000 against 0.211300 in at 0.967000. Both divide, so both thicken the wall as they fall.'),
  ('linesizing', 'advanced', 'module', 'm01-the-wall-a-code-demands', 6, 'The joint factor and the temperature derate both sit in the Barlow denominator beside the design factor rather than beside the specified minimum yield. What is that placement saying?', '["That both of them are measured properties of the delivered pipe, recorded on the mill certificate alongside the yield, which is why a seamless pipe earns 1.000000 and a welded one earns less.", "That both of them scale the design pressure rather than the yield, so a derate of 0.967000 is the code asking the wall to hold 0.967000 of the pressure the design stated.", "That neither of them is a property of the steel: one is confidence in the seam and one is confidence in the steel when it is hot, and both are statements the code makes rather than measurements of the pipe.", "That both of them are corrections the code applies after the wall has been sized, in the same way the corrosion allowance is added to the pressure wall once Barlow has produced it."]'::jsonb, 2, 'A derate of 0.967000 says the code will credit 0.967000 of the specified minimum yield at the temperature the line runs at. The steel did not change and what the code will credit it with did.'),
  ('linesizing', 'advanced', 'module', 'm01-the-wall-a-code-demands', 7, 'Two published cases run on 8.625000 in at 42000.000000 psi and 1000.000000 psig. One is Class 1 with an allowance of 0.062500 in and returns a required wall of 0.2051091270 in; the other is Class 3 with an allowance of 0.000000 in and returns 0.2053571429 in. What should be read into how close those two walls are?', '["That the design factor and the corrosion allowance are interchangeable levers, so a designer may trade 0.062500 in of allowance against the step from a factor of 0.720000 to one of 0.500000 and order either wall.", "That the location class has little effect at this diameter, since the step from Class 1 to Class 3 moved the required wall by less than a thousandth of an inch on an 8.625000 in pipe.", "That both cases were sized at the same 1000.000000 psig and both rate back to 1000.000000 psig, so the two walls are the same quantity measured under two conventions.", "Nothing about the codes agreeing on steel: one wall is a thinner pressure part carrying an added allowance and the other is pure pressure wall under a stricter factor of 0.500000, so two unlike quantities have landed near each other."]'::jsonb, 3, 'The Class 1 case spends part of its 0.2051091270 in on metal that holds no pressure, and the Class 3 case spends all of its 0.2053571429 in on pressure. A comparison of required walls across different allowances is not a comparison of strength.'),
  ('linesizing', 'advanced', 'module', 'm01-the-wall-a-code-demands', 8, 'The mill rolled the SOKU line in 0.375000 in and the rating is read back off that wall at Class 3. With the allowance respected it returns 1019.607843 psig and with the allowance left out it returns 1529.411765 psig. What separates the two answers?', '["The second call has been made at Class 1 rather than Class 3, which is the only way a rating on one wall can return two figures, and 1.500000 is the ratio of the two design factors.", "The factor of 1.500000 between them is the gross wall over the net rather than anything about this pipe, because the allowance is an argument of the rating call and the caller chooses whether to respect it.", "The first call rates the wall the design asked for and the second rates the wall the mill rolled, so 1.500000 is the ratio of 0.419231 in to the wall actually delivered.", "The engine warns on the second call and returns the higher figure only so that a reviewer can see what the corrosion allowance is worth in pressure terms, which is why both 1019.607843 psig and 1529.411765 psig appear on the same row."]'::jsonb, 1, 'Both calls are legal, both are correct for what they were asked, and neither warns. A guard cannot fix a question that was fully formed and simply wrong.'),
  ('linesizing', 'advanced', 'module', 'm01-the-wall-a-code-demands', 9, 'A reviewer is handed one figure only, 1019.607843 psig, for a line whose design pressure was 1200.000000 psig. What has that single figure told them about the pipe in the ground?', '["That 0.375000 in is thinner than the 0.419231 in Class 3 demanded, which the rating can only say by returning a pressure below the one the design asked for.", "That the design pressure was never achievable on this pipe, since no wall in the SOKU table rates back above 1019.607843 psig once the allowance is respected in the call.", "That the allowance has already been consumed, so the figure is the pressure the line will hold at the end of its design life rather than on the day it is commissioned.", "That the rating and the design use different codes, and 1019.607843 psig is the B31.4 reading of a wall that was specified to B31.8."]'::jsonb, 0, 'The design wall is a requirement and the rolled wall is a fact, and the two separate the moment the mill rounds. Rating a line on the wall it was designed to have hides that separation.'),
  ('linesizing', 'advanced', 'module', 'm01-the-wall-a-code-demands', 10, 'The B31.8 Class 4 published case runs 720.000000 psig on 6.625000 in at 35000.000000 psi with a joint factor of 1.000000, a derate of 0.967000 and an allowance of 0.050000 in. It returns a design factor of 0.400000, a required wall of 0.2261707785 in and a rating back of 720.000000 psig. What is unusual about this row?', '["It is the only published case whose rating does not close on the pressure it was sized at, because the derate of 0.967000 is applied in the sizing direction and not in the rating direction.", "It is the only published case whose design factor is not the 0.720000 that B31.4 and B31.8 Class 1 share, which is what makes it the case that exercises the class table.", "It is the only published case carrying a corrosion allowance, so it is the only one where the required wall and the pressure wall are different numbers.", "Three of the code''s levers are in play on one case: the location class through a factor of 0.400000, the temperature derate at 0.967000 and an allowance of 0.050000 in."]'::jsonb, 3, 'The Class 3 published case also runs a design factor other than 0.720000, at 0.500000, and the Class 1 case at 1000.000000 psig also carries an allowance, of 0.062500 in. What this row does is carry three levers at once.'),
  ('linesizing', 'advanced', 'module', 'm01-the-wall-a-code-demands', 11, 'Every wall this module sizes reads back to the pressure it was sized for. What does that round trip prove, and what does it leave open?', '["It proves the design factors are correctly applied in both directions, which is the only check available on a code factor, and it leaves open only whether the mill rolled the wall the design asked for.", "It proves the Barlow form is the right form for a thin-walled line pipe, and it leaves open whether the joint factor and the temperature derate belong in the denominator beside it.", "It proves the two directions are consistent with each other, which is a statement about arithmetic, and it leaves entirely open whether 0.720000 is the right factor for the route.", "It proves nothing at all, since a relation inverted against itself must close, and the five rows reading 1200.000000 psig are a tautology rather than a check."]'::jsonb, 2, 'A round trip cannot reach a question about whether the code is right. The five SOKU rows and the four published cases all close, and none of them says anything about the route.'),
  ('linesizing', 'advanced', 'module', 'm01-the-wall-a-code-demands', 12, 'Across the four B31.8 classes the SOKU pressure wall runs from 0.204327 in to 0.367788 in while the required wall runs from 0.329327 in to 0.492788 in. Why does the step between the two columns hold while both of them grow?', '["The allowance is scaled by the design factor in the same proportion as the pressure wall, so both columns grow together and the step between them stays in the same ratio down the table.", "The three code factors divide and so they scale the pressure wall, while the allowance adds, so the same 0.125000 in is placed on top at every class.", "The engine holds the required wall to the nearest rolled size at each class, so the step is the rounding rather than the allowance and it happens to be constant across these four classes.", "The step holds because all four rows share a design pressure of 1200.000000 psig, and it would move if the classes were compared at different pressures."]'::jsonb, 1, 'That is what an added term looks like standing beside scaled ones. A pressure wall of 0.294231 in and a required wall of 0.419231 in at Class 3 are separated by the same figure as the pair at Class 1.'),
  ('linesizing', 'advanced', 'module', 'm01-the-wall-a-code-demands', 13, 'A wall call arrives with no design pressure. What comes back, and what is notable about the wording?', '["An object carrying the message that wall thickness needs positive design pressure, OD and SMYS, which names all three of the inputs Barlow cannot proceed without rather than only the one that was missing.", "A thrown error naming designPsig, since a missing required argument is the one case in this engine that leaves the ordinary return path rather than answering with a message.", "An object carrying a message naming the design pressure alone, because the engine walks its required arguments in the order Barlow needs them, reports the first one it finds missing and stops looking before the outside diameter is ever examined.", "A required wall of 0.000000 in with the design factor still reported, since Barlow with a zero numerator is arithmetically well defined and the caller is left to notice it."]'::jsonb, 0, 'This engine throws nothing. The message names the three inputs together, so it narrows the problem to the call rather than to the argument.'),
  ('linesizing', 'advanced', 'module', 'm01-the-wall-a-code-demands', 14, 'A line leaves a Class 1 stretch and enters a Class 3 stretch, and the wall rolled for the empty end is the SOKU Class 1 wall of 0.329327 in. What is wrong with carrying it through?', '["Nothing, provided the rating of 1200.000000 psig is recorded, since both walls rate back to the same pressure and the rating is what the operator is held to.", "The Class 1 wall is legal on the Class 3 stretch under B31.4, which uses a flat factor of 0.720000, so the only requirement is that the line be declared to that code before it is commissioned.", "The Class 3 stretch demands 0.419231 in, and the class is a property of each stretch of route rather than of the pipeline, so the wall schedule has to change where the surroundings do.", "The two stretches need the same wall because the design pressure has not changed, and what has to change instead is the corrosion allowance, which rises with the class."]'::jsonb, 2, '0.329327 in is thinner than the 0.419231 in that stretch demands. One line can hold several classes, and the wall follows the route.'),
  ('linesizing', 'advanced', 'module', 'm01-the-wall-a-code-demands', 15, 'The published B31.4 case returns a required wall of 0.2451923077 in at an allowance of 0.000000 in. Why can that figure not be set beside the SOKU Class 3 required wall of 0.419231 in as a comparison of two walls?', '["The two were sized at different pressures, 1440.000000 psig against 1200.000000 psig, and a required wall may only be compared against another sized at the same design pressure.", "One was produced under B31.4 and the other under B31.8, and the two codes define the required wall differently, so the figures are not the same quantity whatever the allowance.", "0.2451923077 in is printed to ten decimals and 0.419231 in to six, so the two are reported at different precisions and cannot be differenced.", "With no allowance the pressure wall and the required wall are the same number, so 0.2451923077 in is pure pressure-carrying steel while 0.419231 in carries 0.125000 in that holds no pressure."]'::jsonb, 3, 'The SOKU pipe at Class 3 has 0.294231 in doing structural work. That is the figure the published case''s 0.2451923077 in stands beside, and the comparison still has two codes and two pressures in it.'),
  ('linesizing', 'advanced', 'module', 'm02-the-pig-and-what-it-pushes', 1, 'The OGBIA line holds 1633.5349 bbl at a bore of 7.981000 in over 26400.000000 ft. Which properties of the fluid in it entered that figure?', '["The density, which is what converts the swept cubic feet into barrels through the 5.6145833333333 cubic feet per barrel the package measures out of the engine.", "The density and the viscosity together, which set the Reynolds number of 48431.2523 that the volume call reads its flow area from.", "None of them, because a line volume is geometry, so a line full of crude and a line full of gas hold the same 1633.5349 bbl.", "The holdup of 0.060000, which is the input that turns a bore and a length into the barrels a line is reported to hold."]'::jsonb, 2, 'Bore and length are the only inputs. The holdup enters one step later and turns 1633.5349 bbl into the 98.0121 bbl a sphere pushes ahead of it.'),
  ('linesizing', 'advanced', 'module', 'm02-the-pig-and-what-it-pushes', 2, 'The package types a barrel into neither module. How is the figure of 5.6145833333333 cubic feet per barrel obtained from lineHydraulics, and what kind of figure is it?', '["By asking that module for the flow area times the length over its own line volume, and what comes back is exact by definition rather than by measurement.", "By dividing the line volume of 1633.5349 bbl by the volume the golden oracle reports in SI units, which makes it a measured agreement between two implementations rather than a definition.", "By reading it from the catalogue the roughnesses and the grade yields come from, which is why an unknown entry is NaN.", "By the erosional velocity times the flow area over the seconds in a day, which is the form lineHydraulics is asked."]'::jsonb, 0, 'chokePerformance answers the same kind of question about itself with 5.6145833333333, and the ratio of the two is 1.0000000000000. A figure that is exact by definition is confirmed by asking two modules rather than by reading one source.'),
  ('linesizing', 'advanced', 'module', 'm02-the-pig-and-what-it-pushes', 3, 'The swept volume is 98.0121 bbl at a holdup of 0.060000 on a line holding 1633.5349 bbl. Where did that holdup of 0.060000 come from?', '["From the Beggs and Brill correlation inside this engine, which works the holdup out from the rate and the inclination before the sweep is taken against it.", "From the line volume and the swept volume, since the engine solves for the holdup that reconciles the two and then reports it back beside the sweep it produced.", "From the erosional check, which returns the fraction of its ceiling a line is using and hands that same fraction on as the liquid standing in the bore.", "From somebody outside this engine, because there is no flow regime, no slip and no holdup correlation anywhere in it and a holdup is taken as an input wherever one is needed."]'::jsonb, 3, 'The engine''s own header says the holdup is supplied. A sweep of 0.060000 on 1633.5349 bbl gives 98.0121 bbl, and every figure downstream of that sweep is worth exactly what the number somebody else measured is worth.'),
  ('linesizing', 'advanced', 'module', 'm02-the-pig-and-what-it-pushes', 4, 'In the holdup sweep the column reading the swept volume as a fraction of the line volume reproduces the holdup column exactly, 0.020000 against 0.020000 and 0.500000 against 0.500000. What does that establish?', '["That the sweep has been normalised against the line volume before it was reported, so the two columns would reproduce each other even if the underlying relation were not a multiplication.", "That the swept volume is the line volume scaled by the holdup with nothing else in the relation at all.", "That the holdup was solved for rather than supplied, because a holdup that had been handed in would not reproduce itself when it is read back out of the sweep it produced.", "That the line volume of 1633.5349 bbl cancels out of the sweep entirely, so the swept volume at a stated holdup is the same on a line of any bore and any length."]'::jsonb, 1, 'At a holdup of 1.000000 the sweep is the whole 1633.5349 bbl and at 0.000000 it is 0.0000 bbl. Nothing else enters between those two ends.'),
  ('linesizing', 'advanced', 'module', 'm02-the-pig-and-what-it-pushes', 5, 'The holdup guard is read on both of its sides. Which pair of values does the engine answer and refuse, and what real condition sits at the limit?', '["It answers 1.000000 and refuses 1.000001, and the value at the limit is a line running liquid full.", "It answers every value below 1.000000 and refuses 1.000000 itself, because a line completely full of liquid has no gas behind the sphere to drive it and the engine excludes that case.", "It answers 1.000001 and refuses 1.000000, because this guard is written to exclude its own limit and to admit the first representable step past it instead.", "It answers any holdup it is handed and refuses none, because the range is enforced one stage later by the interval call, which is also where the catcher limit is read."]'::jsonb, 0, 'A holdup above one is refused with the message that holdup must be between 0 and 1. A guard that refuses its own limit is as wrong as one that accepts nonsense, which is why both sides are read.'),
  ('linesizing', 'advanced', 'module', 'm02-the-pig-and-what-it-pushes', 6, 'A sphere crosses 26400.000000 ft of the OGBIA line at 3.000000 ft/s and the engine returns a run of 2.444444 hours. What does it report beside that figure, and why does that matter?', '["The line velocity of 2.244621 ft/s, so that a reader can see the margin between the fluid and the sphere and judge whether the sphere will be driven along at all.", "The seconds per hour of 3600.000000, because the engine works internally in seconds and prints hours, and it reports the conversion so the round trip can be checked.", "The speed it was given, 3.000000 ft/s, because a run time is a length over a speed somebody stated rather than one the engine worked out.", "The Reynolds number of 48431.2523, so a reader can see whether the line ran turbulent while the sphere was in it."]'::jsonb, 2, 'Nothing about the fluid enters a run time. The density, the viscosity and the holdup are all absent from it, and the speed is a choice.'),
  ('linesizing', 'advanced', 'module', 'm02-the-pig-and-what-it-pushes', 7, 'On the OGBIA line the fluid moves at 2.244621 ft/s and the sphere in the pigging duty is driven at 3.000000 ft/s. What follows from the engine taking the second of those as an input?', '["The engine scales the stated speed towards the line velocity before it reports the run, which is why 2.444444 hours falls between the two crossings that the pair of speeds on their own would give.", "The run time is exactly as good as the speed somebody stated, and passing the line velocity in its place returns a wrong run with nothing beside it to mark the substitution.", "The sphere is driven by the fluid behind it, so the engine derives 3.000000 ft/s from the rate of 12000.000000 bpd and the bore rather than taking any speed as an input.", "The two figures have to agree before a run is quotable, and the engine refuses a pig run whose speed differs from the line velocity by more than the erosional fraction of 0.165707."]'::jsonb, 1, 'A pig is pushed by the fluid behind it and does not travel at the fluid''s average velocity by default. This engine does not attempt the relationship at all.'),
  ('linesizing', 'advanced', 'module', 'm02-the-pig-and-what-it-pushes', 8, 'At a holdup of 0.060000 the OGBIA sweep of 98.0121 bbl goes into a 250.000000 bbl catcher and the engine returns 3.7997 days. What are the two things filling that vessel, and in which order does the arithmetic take them?', '["The dropout fills the vessel first, over 6.2500 days, and the sweep is what arrives once it is already full, which is why the catcher has to be emptied ahead of every run.", "The two are added together and compared against the vessel, so the interval is the catcher size over the sum of the swept volume and the daily dropout.", "The sweep sets the interval on its own, and the dropout of 40.000000 bpd decides only whether the vessel is large enough to receive what the sphere pushes in.", "The sweep claims its room first, leaving 151.9879 bbl, and the dropout of 40.000000 bpd then fills whatever is left over."]'::jsonb, 3, 'Liquid arrives two ways, continuously as dropout and all at once as the sweep. The room left after the sweep is 151.9879 bbl and at 40.000000 bpd that room lasts 3.7997 days.'),
  ('linesizing', 'advanced', 'module', 'm02-the-pig-and-what-it-pushes', 9, 'The interval column is longest at 6.2500 days and has shortened to 2.1662 days by a holdup of 0.100000. Why is the top row the longest interval this line can have?', '["A dry line has no liquid to drop out of it either, so the figure on that row is the time the catcher takes to fill from the line volume of 1633.5349 bbl instead.", "The engine imposes a ceiling of 6.2500 days on any interval it will report, so the top row is where that ceiling is reached rather than where the sweep is smallest.", "At a holdup of 0.000000 the sweep is 0.0000 bbl, so the whole 250.000000 bbl is available to the dropout and nothing has been taken away first.", "The dropout of 40.000000 bpd is itself a function of the holdup, so a holdup of 0.000000 also drips slowest."]'::jsonb, 2, 'An interval is the room left after the sweep over the dropout. At a sweep of 0.0000 bbl no room has been taken, so the pure dropout case sits at the top of the column.'),
  ('linesizing', 'advanced', 'module', 'm02-the-pig-and-what-it-pushes', 10, 'At a holdup of 0.200000 the interval column stops reporting days and returns a message instead. What does that message say, and what is unusual about it in this engine?', '["It says that holdup must be between 0 and 1, and it is unusual because the value being refused sits inside the range the very same guard accepts everywhere else in the module.", "It says the sweep alone already exceeds the slug limit and names the two fixes, pig more often or resize the catcher, so it prescribes where the other refusals only describe.", "It says that an interval needs a positive slug limit and dropout rate, and it is unusual because both of those were supplied on this row and the engine declined anyway.", "It returns a negative interval with the swept volume printed beside it, and it is unusual because it is the one place this engine reports a result it already knows to be impossible."]'::jsonb, 1, 'At a holdup of 0.200000 the sweep is 326.7070 bbl and there is no room in a 250.000000 bbl catcher for anything at all. The third fix a reader reaches for, accepting a smaller margin, is not available here.'),
  ('linesizing', 'advanced', 'module', 'm02-the-pig-and-what-it-pushes', 11, 'The same refusal about the slug limit comes back from the OGBIA sweep of 98.0121 bbl when the catcher is 60.000000 bbl rather than 250.000000 bbl. What does that pair of cases show about the message?', '["That it names a relation between a sweep and a vessel rather than a fault in either, so a sweep that is too large and a vessel that is too small produce one sentence.", "That the message is keyed to the holdup, since a vessel of 60.000000 bbl is refused only once the holdup has risen past the 0.100000 row of the sweep table.", "That the engine sizes the catcher, since it refuses any vessel smaller than the swept volume it has just computed and thereby states the minimum that vessel must be.", "That the sweep is recomputed against the vessel, because a 60.000000 bbl catcher returns a different swept volume from a 250.000000 bbl one on the same line."]'::jsonb, 0, 'The slug a catcher has to hold is computed in this engine and the vessel that holds it is sized in the separation work. The two halves meet at the swept volume.'),
  ('linesizing', 'advanced', 'module', 'm02-the-pig-and-what-it-pushes', 12, 'Three published runs return sweeps of 128.6394 bbl at a holdup of 0.120000, 257.4834 bbl at 0.050000 and 11.6211 bbl at 0.350000. What sets the size of a slug first?', '["The holdup, since the sweep is a straight multiplication by it, so the run at 0.350000 delivers the largest of the three slugs on the strength of its fraction alone.", "The length, since 52800.000000 ft is the longest of the three and the bore enters only at a single station.", "The pig speed, since all three runs are driven at 5.000000 ft/s and a faster sphere gathers up more liquid.", "The line volume, since the largest holdup on the smallest pipe delivers the smallest sweep and the lowest holdup on the biggest pipe delivers the largest."]'::jsonb, 3, 'The three line volumes are 33.2033 bbl, 1071.9949 bbl and 5149.6679 bbl. Slug size is set by the line volume first and by the holdup second.'),
  ('linesizing', 'advanced', 'module', 'm02-the-pig-and-what-it-pushes', 13, 'The swept volume carries two refusals of its own. Which pair are they, and what does each one guard?', '["A swept volume needs a positive bore and length is the geometry refusing, and a pig run needs a positive length and speed is the second refusal the same sweep raises when the sphere does not move.", "A swept volume cannot be negative is the geometry refusing, and an interval needs a positive slug limit and dropout rate is what a sweep returns when no catcher has been stated for it.", "A swept volume needs a positive bore and length is the geometry refusing to make a volume out of nothing, and a swept volume cannot be negative is the interval refusing an impossible input from upstream.", "A swept volume needs a positive bore and length covers both cases, since a negative sweep can only come from a negative length and the engine reports it under that same sentence."]'::jsonb, 2, 'The boundary is inclusive where it should be. A swept volume of exactly 0.000000 bbl is accepted, because a dry line really does deliver nothing, and it is -0.000001 that is refused.'),
  ('linesizing', 'advanced', 'module', 'm02-the-pig-and-what-it-pushes', 14, 'Ask for the volume of a line with no bore and the answer is NaN rather than an object carrying an error string. Why is that return shaped the way it is?', '["The volume is a bare number with nowhere to put a message, so it answers NaN by documented contract and the functions wrapping it are what refuse in words.", "The volume is computed before any guard runs, so the NaN is the arithmetic arriving ahead of them.", "A missing bore is a state the method has no answer for rather than a meaningless input, and this engine answers the first of those classes with NaN and the second with an error string.", "The volume shares a return with the friction factor, so its refusal rides in the regime field as invalid."]'::jsonb, 0, 'Three returns sit outside the refusal contract on purpose. The Reynolds number and the line volume are bare numbers, and the friction factor carries its refusal in the regime it already returns.'),
  ('linesizing', 'advanced', 'module', 'm02-the-pig-and-what-it-pushes', 15, 'A receiving facility is sized on the OGBIA line volume of 1633.5349 bbl. What has gone wrong, and by how much on the nominal duty?', '["Nothing has gone wrong, because the sweep is the line volume less the liquid that stays behind, so 1633.5349 bbl bounds it.", "The line volume is the right quantity in the wrong units, since 1633.5349 bbl is a figure in cubic feet until the 5.6145833333333 cubic feet per barrel has been applied to it.", "The facility should have been sized on the room left in the catcher, 151.9879 bbl.", "The slug is the sweep rather than the line, so the facility has been sized on 1633.5349 bbl where the sphere delivers 98.0121 bbl at a holdup of 0.060000."]'::jsonb, 3, 'The line holds 1633.5349 bbl and a run delivers a fraction of it. Sizing a catcher on the line volume oversizes it by whatever the holdup was never going to be.'),
  ('linesizing', 'advanced', 'module', 'm03-where-the-correlations-stop', 1, 'On the OGBIA pipe the friction factor reads 0.0304761905 at a Reynolds number of 2099.9999999 and 0.0488545386 at 2100.0000. How large is that step, and what produced it?', '["A ratio of 1.603040, and it is the pipe''s roughness entering the calculation for the first time, since the laminar branch below the boundary carries no roughness term at all and the turbulent branch above it does.", "A ratio of 1.603040, and it is the engine leaving the laminar law and starting the turbulent one at the boundary it draws.", "A ratio of 1.603040, and it is the transition itself, which is a real physical change in the flow that both of the branches are written to reproduce on their own side of the boundary.", "A ratio of 1.603040, and it is the fixed point in the friction solve failing to settle so close to the boundary, which is why the two figures either side of it disagree so widely."]'::jsonb, 1, 'Nothing physical happens across that interval. The engine leaves the laminar law and starts the turbulent one, and the discontinuity is the price of having no correlation for the band between the two branches.'),
  ('linesizing', 'advanced', 'module', 'm03-where-the-correlations-stop', 2, 'Between a Reynolds number of 2099.9999999 and one of 2100.0000 the friction factor moves by a ratio of 1.603040. What changed in the line over that interval?', '["The flow crossed from a laminar profile into a turbulent one, which is the step being reported.", "The relative roughness became significant, because a laminar flow cannot feel a wall that a turbulent flow can, so the pipe started behaving as a rough pipe over that interval.", "The Reynolds number crossed the value at which the engine begins to call the flow turbulent, which is 2100 for the label and 4000 for the arithmetic, so both changed at once.", "Nothing did. The fluid, the pipe and the duty are identical, and only the correlation being applied to them is different."]'::jsonb, 3, 'A physical transition is gradual and messy. This one is a switch placed where the engine draws its boundary, and the size of the step is a property of the two correlations meeting there.'),
  ('linesizing', 'advanced', 'module', 'm03-where-the-correlations-stop', 3, 'Inside the band from a Reynolds number of 2100 to one of 4000 the engine returns a regime word and a friction factor together. What is the relationship between those two fields there?', '["They come from different assumptions: the word says transitional and the number was computed on the turbulent branch, and nothing in the object marks the disagreement.", "They agree, since the engine computes a transitional friction factor from a correlation written for the band and reports the matching word beside it in the same object.", "They contradict each other outright, because a value computed on the laminar branch is reported under a turbulent label, which is the direction that makes the band permissive.", "They are independent, because the regime word is set from the pipe''s relative roughness while the friction factor is set from the Reynolds number alone."]'::jsonb, 0, 'The regime word is not wrong and the friction factor is not a fabrication. They are two answers from different assumptions returned together, which is why the band from 2100 to 4000 is held.'),
  ('linesizing', 'advanced', 'module', 'm03-where-the-correlations-stop', 4, 'The band between the two branches is held for the literature rather than smoothed over with an interpolation. Why is holding it the better treatment?', '["Interpolating across the band would break the round trip, since a friction factor read back through the Reynolds number would no longer return the value it was computed from.", "The engine cannot interpolate, because the two branches live in different modules.", "An interpolation would hand back a curve that looks like every other answer, and holding it keeps the missing correlation visible as a limit.", "An interpolation would move the boundary from 2100 to 4000, and a moving guard cannot be read on both sides."]'::jsonb, 2, 'Nothing physical happens between a Reynolds number of 2099.9999999 and one of 2100.0000. The friction factor moves from 0.0304761905 to 0.0488545386 because the engine changes laws there, which is a fact about the engine rather than about the flow.'),
  ('linesizing', 'advanced', 'module', 'm03-where-the-correlations-stop', 5, 'Colebrook was published for a relative roughness reaching about 0.05. Which of the five rows the digest walks at a Reynolds number of 1000000.0000 sit outside that range?', '["Only the row at 0.500000, returning 0.3308894263, since a relative roughness of 0.200000 is still inside the range the correlation was fitted over and the engine flags it for that reason.", "None of them, because the engine answers all five and raises nothing, and a correlation that is being asked outside its range is refused by this engine in the ordinary way.", "The rows at 0.050000 and above, returning 0.0715737539 upward, since the published limit is where the fit stops being trustworthy rather than where it stops being defined.", "The rows at 0.100000, 0.200000 and 0.500000, returning 0.1016731332, 0.1557055485 and 0.3308894263."]'::jsonb, 3, 'The engine answers all five and flags none of them. The last row describes a pipe whose wall roughness is half its own bore, which is a geometry the word roughness stops covering.'),
  ('linesizing', 'advanced', 'module', 'm03-where-the-correlations-stop', 6, 'A friction factor of 0.3308894263 comes back from a relative roughness of 0.500000. Why is nothing about that return a warning to the caller?', '["It is accompanied by the regime word invalid, which a caller who is reading only the friction factor will miss, so the warning is present and is simply in the field beside the one being read.", "It arrives in the same field, in the same shape and at the same precision as a friction factor from the middle of the fit, and the curve stays smooth across the whole table.", "The engine rounds an extrapolated friction factor to fewer digits than a fitted one, so the warning is in the precision and it is easy to overlook on a single row.", "The value is large enough to be obviously wrong, so the engine leaves it to the caller to notice, which is the same treatment it gives a Reynolds number in the transitional band."]'::jsonb, 1, 'A correlation outside its range does not usually produce nonsense. It produces a plausible number, which is worse, because nonsense gets caught.'),
  ('linesizing', 'advanced', 'module', 'm03-where-the-correlations-stop', 7, 'Roughness carries a guard and a relative roughness of 0.500000 passes straight through it. What is that guard actually protecting?', '["The published range of the correlation, which the engine enforces at the boundary of about 0.05, so a relative roughness of 0.500000 passes only because it was supplied as an absolute roughness instead.", "The convergence of the friction solve, since a negative roughness is the one input that stops the fixed point settling.", "Meaning rather than validity: a length cannot be negative, so a negative roughness is refused, while a roughness outside anybody''s fit is a perfectly meaningful quantity.", "The flow area, since a roughness approaching the bore would leave nothing for the flow to move through."]'::jsonb, 2, 'A negative roughness returns the message that absolute roughness is a length and cannot be negative. The presence of one guard invites the assumption that the other exists too.'),
  ('linesizing', 'advanced', 'module', 'm03-where-the-correlations-stop', 8, 'Weymouth takes no friction factor and no roughness. How does the digest recover the friction Weymouth is assuming?', '["By asking General Flow what friction factor would make its own rate match the Weymouth rate, using the fact that a General Flow rate goes as one over the square root of the friction factor.", "By reading the Weymouth coefficient out of the published form directly, since the fully rough friction law is stated inside it and only has to be rearranged to be seen.", "By comparing the Weymouth rate against the Panhandle A and Panhandle B rates on the same line, since the three published forms bracket the friction factor between them.", "By running the same line at a very low duty, where the friction term falls away and what remains of the Weymouth rate is the friction law it was carrying."]'::jsonb, 0, 'On the 7.981000 in bore General Flow settles on 0.0121761733 and the figure that would make it match Weymouth is 0.0160098631. The measurement is derived from the two engine rates and the engine friction factor on each row.'),
  ('linesizing', 'advanced', 'module', 'm03-where-the-correlations-stop', 9, 'Across bores of 6.065000 in, 7.981000 in, 11.938000 in and 15.000000 in the friction factor implied by Weymouth falls from 0.0175440472 to 0.0129730762. What does that direction tell a reader?', '["That Weymouth parts further from General Flow as the bore grows, since the settled figure of 0.0107219615 and the implied figure of 0.0129730762 are the furthest apart of the four rows.", "That the implied figure is tracking the relative roughness, which falls as the bore grows on a pipe of fixed absolute roughness, so Weymouth is carrying a Colebrook friction law after all.", "That the implied figure is following the Reynolds number rather than the diameter, which is what a smooth turbulent law does.", "That Weymouth''s friction law depends on the diameter rather than on the Reynolds number, which is the signature of a fully rough law."]'::jsonb, 3, 'The implied figure is above the computed one on every row, which is why Weymouth reads lower than General Flow on all four bores. Weymouth is assuming a rougher pipe than Colebrook computes here.'),
  ('linesizing', 'advanced', 'module', 'm03-where-the-correlations-stop', 10, 'A line is internally coated and an identical line is used steel. What do the four transmission forms make of that difference?', '["Only General Flow can be told about it, because it is the one form that takes a roughness and reports the friction factor it reached.", "All four can be told about it through the transmission efficiency, which is the input the published forms provide for exactly this purpose and which is bounded above by 1.000000.", "Weymouth handles it through its fully rough law, which adjusts to the wall condition.", "None of them, since General Flow discards the roughness before the rate is formed."]'::jsonb, 0, 'Weymouth has no roughness input at all, so a coated line and a line of used steel hand it the same inputs and receive the same rate. Its friction is not a pipe property anybody entered.'),
  ('linesizing', 'advanced', 'module', 'm03-where-the-correlations-stop', 11, 'On a nearly dead trunk Weymouth gives 10466013.4729 scfd against General Flow''s 11016984.8816 scfd, a ratio of 0.949989. On the same pipe at full duty the ratio is 0.894987. What does the pair establish?', '["That the nearly dead case is outside the range of both forms, which is why they disagree there by 0.050011 while the full duty case is inside it and disagrees by only a fraction of that.", "That the distance between two forms moves with the duty on one unchanged pipe, 0.050011 against 0.105013, and neither form reports which state it was handed.", "That General Flow reads high whenever the friction factor it settles on is below 0.0126337788.", "That the two forms converge as the duty rises, since 0.894987 is the closer of the two to unity."]'::jsonb, 1, 'The two forms are closer together when the line is barely flowing than when it is working. Agreement between two forms on one duty is a fact about those forms at that duty.'),
  ('linesizing', 'advanced', 'module', 'm03-where-the-correlations-stop', 12, 'A gas transmission form returns a rate to four decimals on a line with five psi across the whole of it. What has that rate established?', '["That the line is inside the developed turbulent region the published forms assume, since a form that had been handed a state outside its assumptions would have returned an error object instead.", "That the rate is the one the line will actually carry, since the four forms differ only in their exponents and all four are fitted to the same measured transmission data.", "The arithmetic, done correctly, and nothing at all about whether the form applies to a line in that state.", "That the flow is steady, because an unsteady line cannot produce a single rate and the engine would have returned the last iterate of its solve with no flag beside it."]'::jsonb, 2, 'A gas transmission form assumes a flow well into the turbulent region, developed and steady. None of the four asks whether the line it was handed is that kind of line.'),
  ('linesizing', 'advanced', 'module', 'm03-where-the-correlations-stop', 13, 'Of the four transmission forms, only one reports anything about the pipe beyond a rate. Which, and why does that matter?', '["General Flow, which returns the friction factor it settled on, and that single field is the only place a reader can see an assumption being made and test it.", "Weymouth, which returns the fully rough friction law it applied, so a reader can compare it against a computed Colebrook figure on the same line.", "Panhandle B, which reports the efficiency it was run at, so a reader can see how much of the rate came from the multiplier rather than from the line.", "General Flow, which returns the Reynolds number it reached, so a reader can check the flow was turbulent before accepting the rate the form produced."]'::jsonb, 0, 'Weymouth, Panhandle A and Panhandle B report a rate and nothing else. The form with the most visible assumption is also the only one that can be argued with.'),
  ('linesizing', 'advanced', 'module', 'm03-where-the-correlations-stop', 14, 'Two answers in this module come out of loops. What is missing from both returns, and how far does the digest go in describing it?', '["There is no converged field, and the digest records that the General Flow solve was found not to settle on the largest of the four bores, which is why that row carries an implied friction factor.", "There is no iteration count, and the digest records that the friction solve is the only one of the two that iterates, since the General Flow rate is formed in a single pass once the friction factor is known.", "There is no residual reported, and the digest records that the two loops disagree by 0.0126337788 on the nearly dead trunk, which is the size of the convergence gap between them.", "There is no converged field, no iteration count and no residual, and the digest records that both loops converge everywhere it looked."]'::jsonb, 3, 'The friction factor solve runs a fixed point and the General Flow solve runs a rate and a friction factor against each other. No wrong number has been produced by either, and what is absent is the evidence.'),
  ('linesizing', 'advanced', 'module', 'm03-where-the-correlations-stop', 15, 'A cautious reader runs the same General Flow case twice to see whether the answer is stable. What does the second run tell them?', '["That the loop converged, if the two runs agree, since a loop that stopped while still moving would leave its last iterate at a different value on a second pass through the same inputs.", "That the friction factor is stable and the rate may not be, since only one of them is carried over.", "Nothing at all, because nothing in this engine reads a clock or a random number, so the same case returns the same figure whether or not the loop settled.", "That the answer is reproducible only as far as the four decimals a gas rate is printed at, since a finer drift between two runs would not be visible in the print."]'::jsonb, 2, 'Determinism is a virtue here and it removes the one check a caller might have improvised. The outlet-pressure solve is the contrast, since it refuses in words rather than returning its last guess.'),
  ('linesizing', 'advanced', 'module', 'm04-what-a-refusal-is', 1, 'This engine has one shape for a refusal and keeps to it. What is that shape, and what does it let a caller do?', '["A thrown exception carrying the message, which is why a caller wraps every entry point and handles the whole module''s failures in one place at the top of the chain.", "A null in the field the answer would have occupied, which a caller tests for before reading the value and which cannot be confused with a pressure or a rate.", "A sentinel value the module documents, which is a negative figure in a field that is otherwise always positive, so one comparison catches every failure the engine has.", "An object carrying an error string, which arrives through the ordinary return path, so a caller checks a property rather than catching."]'::jsonb, 3, 'It is never a thrown exception, never a null and never a bare number. A liquid line with no rate comes back as an object saying the drop needs positive rate, bore, length, density and viscosity.'),
  ('linesizing', 'advanced', 'module', 'm04-what-a-refusal-is', 2, 'Why is a NaN or an Infinity returned without an error worse than having no guard at all?', '["It is the one return that leaves the ordinary path, so the caller that knew what to do about it has already unwound by the time the value arrives at the top of the chain.", "It passes the check a caller makes and then propagates into a sizing sweep, a marched profile or a wall specification, each of which carries it forward without complaint.", "It is indistinguishable from an ordinary result, which means the engine cannot report it either, so the failure is invisible on both sides of the call at once.", "It cannot be serialised at all, so a case file that contains one fails to save and the record of the run that produced it is lost along with the value."]'::jsonb, 1, 'An absent guard produces an obviously wrong answer that somebody notices. A NaN is a returned value with no error property beside it, so it survives the test and travels.'),
  ('linesizing', 'advanced', 'module', 'm04-what-a-refusal-is', 3, 'Three returns in this engine sit outside the refusal contract on purpose. Which three?', '["The Reynolds number of a line with no viscosity, the volume of a line with no bore, and the interval whose sweep already overfills the catcher, which prescribes rather than describes.", "The friction factor at a negative relative roughness, the wall with no design pressure, and the outlet-pressure solve on an equation the engine does not carry by name.", "The Reynolds number of a line with no viscosity, the volume of a line with no bore, and the friction factor at a negative relative roughness.", "The volume of a line with no bore, the rating with no wall left after the allowance, and the sweep handed a holdup above one, all three of which answer with a bare number."]'::jsonb, 2, 'All three return NaN, the first two bare and the third in a field beside a regime of invalid. The wall and the sweep cases refuse in the ordinary way, with an object carrying an error string.'),
  ('linesizing', 'advanced', 'module', 'm04-what-a-refusal-is', 4, 'The Reynolds number and the line volume answer NaN while the friction factor answers with a regime of invalid. What explains the difference between those two treatments?', '["The first two are bare numbers with nowhere to put a message, and the friction factor already returns an object with a regime field, so its refusal rides in a field that was there anyway.", "The first two are reached through the ordinary entry points and the friction factor is not, so only the friction factor has a wrapper available to it that can refuse in words.", "The first two are guarding meaningless inputs and the friction factor is guarding a state the method has no answer for, and the engine spells those two classes differently.", "The first two are computed before their guards run and the friction factor after, so the NaN is arithmetic that has already happened and the invalid regime is a guard that fired in time."]'::jsonb, 0, 'Where a function has room for a message it refuses in words, and where it has none it returns a value that cannot be mistaken for a pressure or a rate. The friction factor''s is the tidiest of the three.'),
  ('linesizing', 'advanced', 'module', 'm04-what-a-refusal-is', 5, 'All three of the returns outside the contract print as null in a saved case file. Why, and what does it cost a reader?', '["The encoder replaces any value outside the contract with null so that a stored case always parses, so a reader loses the distinction between a refusal and an ordinary answer.", "A NaN has no JSON spelling, so all three print as null although not one of them is a null the engine chose, and the record cannot say which of the three it holds.", "All three genuinely return null, and what a reader loses is only the message, since the engine attaches a message to an error object and none to a null.", "The engine serialises the regime field ahead of the friction factor, so the two bare numbers inherit the invalid regime and print under it, and the original values are gone."]'::jsonb, 1, 'The engine returned NaN in every one of the three and null is what printing it produced. The regime field is the only thing that distinguishes the third, which is another reason that design is the better one.'),
  ('linesizing', 'advanced', 'module', 'm04-what-a-refusal-is', 6, 'The engine refuses two different classes of thing in the same shape. What is the distinction, and why does it matter to whoever reads the message?', '["A state the method has no answer for is refused with an error object and a meaningless input is refused with a NaN, so the shape of the return is what tells the two apart.", "A state the method has no answer for is reported with the boundary either side of it and a meaningless input is not, so a reader can see which class a message belongs to from the message alone.", "A state the method has no answer for is a failure of the line and a meaningless input is a failure of the engine, so one of them is a design finding and the other is a defect to be fixed.", "A state the method has no answer for had meaningful inputs and led nowhere, and a meaningless input was never attempted, so a reader who conflates them hunts for physics behind a typing error."]'::jsonb, 3, 'A gas line whose outlet meets its inlet has no flow to report, and every input was meaningful. A negative roughness or an efficiency above one was never attempted at all.'),
  ('linesizing', 'advanced', 'module', 'm04-what-a-refusal-is', 7, 'The catalogue of physically meaningless inputs has more entry points than sentences. What are the two counts, and what are the two reasons a sentence appears twice?', '["Twenty-four entries carrying eighteen distinct messages, with six repeated: three are one message guarding two entry points, and three are one guard catching two kinds of bad value.", "Twenty-four entries carrying eighteen distinct messages, all six of the repeats being one guard catching a value above its range and a value below it, in the way the efficiency is refused at each end.", "Eighteen entries carrying twenty-four distinct messages, because six of the entries carry a second sentence naming the boundary the engine accepts on the other side of the guard.", "Twenty-four entries carrying eighteen distinct messages, with six repeated because the same input is reached once through a liquid call and once through a gas call in every one of those cases."]'::jsonb, 0, 'The roughness message answers a liquid friction call and a General Flow call. The efficiency message refuses a value above one and a value below zero. Those are the two different reasons.'),
  ('linesizing', 'advanced', 'module', 'm04-what-a-refusal-is', 8, 'Which set of messages is shared across two different entry points rather than catching two kinds of bad value at one entry point?', '["The efficiency message, the gas length message and the swept volume message, which answer a value above a range and a value below it at the same entry point in each case.", "The gas gravity message, the compressibility message and the absolute temperature message, which are raised both by a transmission form and by the elevation group that reads the same state.", "The roughness message, the elevation message and the corrosion allowance message, which answer a liquid call and a General Flow call, a liquid line and a gas line, and a wall call and a rating call.", "The traverse message, the fitting resistance message and the static gas column message, each of which is reached once from a liquid chain and once from the marched profile above it."]'::jsonb, 2, 'Efficiency is refused above one and below zero by one sentence, a gas line is refused for a zero length and a negative one, and a swept volume is refused for a missing bore and a negative length.'),
  ('linesizing', 'advanced', 'module', 'm04-what-a-refusal-is', 9, 'One message in the meaningless-input catalogue is a physical verdict wearing the shape of an input guard. Which, and what makes it different?', '["The one saying elevation change cannot exceed line length, because a line as tall as it is long is vertical and the verdict is about the geometry rather than about the value supplied.", "The one saying the static gas column alone spends the inlet pressure and the line delivers nothing at any rate, because every input behind it is meaningful and the hill is simply taller than the pressure can pay for.", "The one saying the sweep alone already exceeds the slug limit, because it prescribes two fixes and a guard on a meaningless input has nothing to prescribe.", "The one saying no flow, the outlet pressure meets or exceeds the inlet head, because the inputs are meaningful and the engine still declines to report a rate for the line."]'::jsonb, 1, 'Six of the eighteen protect dimensions, six protect the gas state, three protect the code factors in the wall calculation, one protects the fitting resistance sum and one protects a traverse. The eighteenth belongs to none of those groups cleanly.'),
  ('linesizing', 'advanced', 'module', 'm04-what-a-refusal-is', 10, 'Every guard in this engine is read on both of its sides rather than only on the side that fails. What do the accepted values have in common?', '["Each of them is a real engineering condition: no fittings, the ideal efficiency, a line running liquid full, a vertical line, a pipe not expected to corrode and a dry line.", "Each of them is the value the engine falls back on when the argument is omitted entirely.", "Each of them is a value no real line would ever carry, which is what makes them safe to accept, since accepting an impossible condition cannot mislead a designer who would never ask for it.", "Each of them sits one representable step from a value the engine refuses, and nothing else."]'::jsonb, 0, 'The resistance sum answers at 0.000000 and refuses at -0.000001, the efficiency answers at 1.000000 and refuses at 1.000001, and the holdup runs the same way. None of those limits is an edge case to be tolerated.'),
  ('linesizing', 'advanced', 'module', 'm04-what-a-refusal-is', 11, 'One guard has been walked to the finest resolution the machine offers. Which, and what did that establish?', '["The transmission efficiency, where the engine accepts 1.000000 and refuses 1.000001, which is the finest step any input anywhere in this engine has been read at.", "The corrosion allowance, where the engine accepts 0.000000 in and refuses -0.000001 in, which is the only guard read at a step finer than the results are printed to.", "The liquid holdup, where the engine was walked below 1.000001 to the last value it accepts.", "The rise of a gas line against its length, where a mile-long line accepts 5280.000000000 ft and refuses the next representable value above it, 9.095e-13 ft higher."]'::jsonb, 3, 'There is no physical difference between those two lines. The point is that the boundary is exactly where it claims to be, with no slack built in on either side.'),
  ('linesizing', 'advanced', 'module', 'm04-what-a-refusal-is', 12, 'Why is a guard that refuses its own limit a harder defect to notice than one that accepts nonsense?', '["It produces no message at all, since a guard firing on a legal value returns the same bare NaN that the three documented exceptions return, and nothing marks which of them it was.", "It fires only at the limit itself, which is a value no test suite ever reaches.", "It complains about a valid question, and the usual response is to change the input until the engine stops objecting rather than to suspect the guard.", "It shifts the boundary by one representable step of 9.095e-13 ft, which nothing prints."]'::jsonb, 2, 'Testing only the bad side confirms that a guard exists. Testing both sides establishes where it is, which is why every one of the seven is handed the value on each side.'),
  ('linesizing', 'advanced', 'module', 'm04-what-a-refusal-is', 13, 'Ask each of the five catalogues for an entry it does not carry. What comes back?', '["NaN from fittingK, roughnessOf and gradeYield, null from scheduleRow, and from erosionalC an object naming continuous service at a c factor of 100.", "NaN from all five, since a lookup that cannot answer has no message to attach and the wrapping function is what refuses in words, exactly as the Reynolds number does.", "NaN from fittingK and roughnessOf, null from gradeYield and scheduleRow, and from erosionalC an object carrying an error string naming the service that was asked for.", "An object carrying an error string from all five, since a catalogue miss is a meaningless input rather than a state the method has no answer for and is refused in the ordinary way."]'::jsonb, 0, 'Four of the five say they do not know, in two different spellings. The fifth answers under a label that is not the one it was asked for.'),
  ('linesizing', 'advanced', 'module', 'm04-what-a-refusal-is', 14, 'erosionalC answers an unknown service with continuous service at a c factor of 100. Why was that one left alone?', '["Because the returned object is internally consistent and correctly labelled, so a caller who reads the label can detect the substitution and no repair is warranted at all.", "Because a c factor is a held item with no source read against it, so no return it makes can be more correct.", "Because the three c factors of 100.000000, 125.000000 and 175.000000 are the only services the table carries, so an unknown id can only ever be a caller error rather than a gap.", "Because the RP 14E table belongs to the wellhead engine that two other studios read, so what an unknown service returns there is a decision for that table."]'::jsonb, 3, 'Repairing it here would fix one caller and change the behaviour of two applications that never asked. A caller who reads only the c factor has silently been given a different service''s figure.'),
  ('linesizing', 'advanced', 'module', 'm04-what-a-refusal-is', 15, 'The rating over-rates a line whenever the caller drops the corrosion allowance, and no guard will ever catch it. Why not?', '["The allowance is a property of the pipe rather than an argument of the call, so by the time the rating runs there is nothing left in the inputs for a guard to inspect.", "A guard on the allowance would refuse 0.000000 in, which is a legal value for a line that is not expected to corrode, so the guard would have to reject its own limit.", "Both calls are fully formed and correct for what they were asked, so what went wrong is the choice of question rather than the value of any input.", "The two answers differ by 1.500000 times, which is inside the range a rating can legitimately span across the four location classes, so no threshold could separate them."]'::jsonb, 2, 'The same wall reads 1019.607843 psig with the allowance and 1529.411765 psig without it. A guard cannot fix a question that was fully formed and simply wrong.'),
  ('linesizing', 'advanced', 'module', 'm05-what-the-method-does-not-know', 1, 'The digest lists five things this course teaches as limits and never as answers, while the lessons speak of four held items. How do those two counts fit together?', '["The fifth is the multiphase half, which is absent rather than held, so the lessons drop it from the list of held items and count the remaining four.", "The fifth is the transitional band, which the engine bounds at a Reynolds number of 2100 and 4000, and a bounded item is counted as held by the digest and as closed by the lessons.", "Four of the five are a figure or a law nobody in this package has read a source for, and the fifth is the provenance of the published cases rather than a figure at all.", "The fifth is the efficiency multiplier, which the lessons fold into the fully rough friction law Weymouth assumes, because neither of the two is a property of any pipe that anybody entered."]'::jsonb, 2, 'The four are the API RP 14E c factors, the efficiency multiplier, the band between the branches and the friction law Weymouth assumes. The fifth entry records that every published case in this course is synthetic.'),
  ('linesizing', 'advanced', 'module', 'm05-what-the-method-does-not-know', 2, 'The API RP 14E c factors are 100.000000, 125.000000 and 175.000000. What exactly is unchecked about them?', '["The recommended practice says its own figures are conservative and nobody here has read a source that says how conservative, and the third is labelled operator practice with no publication behind it at all.", "The three figures are correct for the services they name and the engine applies the wrong one to a service it does not carry, so what is unchecked is the lookup rather than the values.", "The figures come from a table the wellhead engine owns, so this course has no way to read them at all and records the three it is handed without seeing the source.", "The three figures are stated without the units they carry, so an erosional velocity computed from one of them cannot be reproduced without assuming what those units were."]'::jsonb, 0, 'A held item is not a wrong number. These are the figures the industry uses and the derived velocities are arithmetically correct, and what is missing is the reading.'),
  ('linesizing', 'advanced', 'module', 'm05-what-the-method-does-not-know', 3, 'The engine refuses a transmission efficiency at or below zero and above 1.000000. Why does that not settle the efficiency question?', '["The bound is applied after the rate is formed, so an efficiency outside it still reaches three of the four transmission forms before the guard is able to catch it.", "A bound is not a source, so knowing the range a value may take says nothing about which value belongs on a line.", "The bound is stated at a precision of 1.000000, which is coarser than the four decimals a gas rate is printed at, so it cannot discriminate between the values a designer would choose between.", "The bound belongs to General Flow alone, since it is the only form that reports what it settled on, and the other three forms carry no bound on the multiplier at all."]'::jsonb, 1, 'Knowing that a value lies above zero and at most 1.000000 leaves every value in that interval available, and the four transmission forms carry no other statement about it.'),
  ('linesizing', 'advanced', 'module', 'm05-what-the-method-does-not-know', 4, 'The band from a Reynolds number of 2100 to one of 4000 is held for the literature. What is being held there?', '["The boundary itself, since the engine could draw it anywhere between 2100 and 4000 and the choice of 2100 is what nobody has read a source for.", "The laminar law, since it is the branch that stops applying at a Reynolds number of 2100 and nothing anywhere in this package stands behind the form that branch carries.", "The regime word, since the arithmetic in the band is sound and only the label the engine attaches to it is the part the package cannot source.", "The question of what a friction factor in that band should be, since the engine computes on the turbulent branch there and labels the answer transitional."]'::jsonb, 3, 'The step across the boundary is 1.603040 times. It is taught as a limit and never graded, and interpolating across it would hand back a curve that looks like every other answer.'),
  ('linesizing', 'advanced', 'module', 'm05-what-the-method-does-not-know', 5, 'The fully rough friction law Weymouth assumes is on the held list even though this course measured it. Why does measuring it not take it off the list?', '["The measurement extracts the law out of the engine and nothing in the package sources the law itself, so what survives is the qualitative statement rather than a figure to grade.", "The measurement was made on four bores only, so the law is held until the remaining published bores have been swept and the implied friction factor confirmed on each of them.", "The measurement depends on the General Flow friction factor, which the digest records as failing to settle on these four bores, so the implied figures inherit an open question.", "The measurement is stated at ten decimals where the goldens work to four, so the figures cannot be compared against an independent implementation and stay unchecked for that reason."]'::jsonb, 0, 'Section 15 measures it by asking General Flow what friction factor would make it agree. What the four rows establish on their own is that Weymouth''s friction depends on the diameter.'),
  ('linesizing', 'advanced', 'module', 'm05-what-the-method-does-not-know', 6, 'What keeps a held item from quietly carrying a graded answer in this course?', '["The engine refuses to compute any value that depends on a held item, which is why an erosional velocity is reported as a limit rather than as a result of the sizing chain.", "The graded fields are drawn from the wall and the pigging chains only, since neither of those touches a c factor, an efficiency or a friction correlation at any step.", "Every value that touches one states its own assumption alongside, so every graded erosional figure states its c factor and every graded gas figure states its efficiency.", "The tolerance on every graded field is widened until it spans the range a held item could move the answer over, so a held item cannot change whether an answer scores."]'::jsonb, 2, 'That turns a held item from a hidden dependency into a stated condition, and a stated condition is something a reader can disagree with.'),
  ('linesizing', 'advanced', 'module', 'm05-what-the-method-does-not-know', 7, 'A reviewer proposes dropping the c factors from the course entirely on the grounds that they are unsourced. What is wrong with that?', '["Nothing is wrong with it, since a value nobody stands behind cannot support an engineering decision and removing it is the only treatment consistent with holding it.", "The c factors are bounded by the engine in the way the efficiency is, and a bounded value has a source in the bound, so they were never truly unsourced in the first place.", "The erosional check would then have no ceiling at all, and a sizing chain with no ceiling would accept any velocity, which is a worse failure than an unsourced one.", "These are the best figures available and an erosional velocity at a stated c factor is a complete answer to a stated question, so the course teaches them and declines only to let one carry a graded conclusion."]'::jsonb, 3, 'Promoting a held figure by repetition is the first mistake and refusing to use it at all is the second. A c factor of 100.000000 quoted in three documents starts to look like a standard.'),
  ('linesizing', 'advanced', 'module', 'm05-what-the-method-does-not-know', 8, 'Every published case behind this course comes from an independent oracle written in Python from the same physics, in SI where the engine works in field units. What can that arrangement prove?', '["That the physics being encoded is the physics of a real pipeline, since an independent implementation reaching the same answer is the strongest confirmation available short of a field test.", "That neither implementation made an arithmetic slip or dropped a conversion, because two encodings in different unit systems disagree the moment one of them does.", "That the engine''s field-unit conversions are correct, which is the only class of error two implementations can differ on once they have been written from one set of equations.", "That the engine converges, since the oracle solves the same implicit relations by a different method and agreement between two methods is what a convergence check would establish."]'::jsonb, 1, 'Agreement between two implementations is evidence about arithmetic. The published wall, pigging and friction cases in this course all carry a golden of that kind.'),
  ('linesizing', 'advanced', 'module', 'm05-what-the-method-does-not-know', 9, 'What is the one class of error a synthetic golden cannot catch?', '["A method that is wrong in both files, because the oracle then agrees with the engine and the two are confidently wrong together.", "A unit error, because the oracle works in SI and the engine in field units, so a conversion applied twice appears in both files and cancels out of the comparison.", "An error in a held item, because neither file has read a source for the c factors or the efficiency and both encode whatever figure the package handed them.", "An error at a boundary, because the oracle carries no guards at all and so cannot be asked what it does on either side of one."]'::jsonb, 0, 'If the physics being encoded is the wrong physics, agreement proves nothing about the world. No measured pipeline is in this course.'),
  ('linesizing', 'advanced', 'module', 'm05-what-the-method-does-not-know', 10, 'Why does the oracle work in SI units when the engine it checks works in bpd, inches, feet, psia and degrees Rankine?', '["Because the published transmission forms are stated in SI and the oracle reproduces them in the units they were published in, which removes one step from the comparison.", "Because the graded capstone fields are stated in SI, so the oracle produces them directly and the engine''s field-unit answers are converted once before they are compared.", "Because a conversion that has been dropped or applied twice cannot survive being written out in two different unit systems, which is the error the goldens exist to catch.", "Because SI avoids the gravitational constant the field form has to carry, and a constant that never appears cannot be typed in wrongly."]'::jsonb, 2, 'Two people encoding the same physics in different unit systems disagree the moment one of them makes an arithmetic slip. Field units are what the engine works in and what this course reports.'),
  ('linesizing', 'advanced', 'module', 'm05-what-the-method-does-not-know', 11, 'One barrel was measured out of two modules by asking each module a question about itself. What were the two questions, and what came back?', '["The line volume over the flow area times the length from lineHydraulics, and the erosional rate over the erosional velocity times the area from chokePerformance, which returned figures whose ratio is 1.0000000000000.", "The swept volume at a holdup of 1.000000 over the line volume from lineHydraulics, and the same ratio taken at the erosional ceiling from chokePerformance, both returning 5.6145833333333.", "The published golden volume against the engine volume in each of the two modules, which is the only measurement available that does not read either source file.", "The flow area times the length over the line volume from lineHydraulics, and the erosional velocity times the area times the seconds in a day over the erosional rate from chokePerformance, both returning 5.6145833333333."]'::jsonb, 3, 'The ratio of the two is 1.0000000000000. Neither figure was read out of a source file, which is what makes each one a measurement of the module rather than a reading of its code.'),
  ('linesizing', 'advanced', 'module', 'm05-what-the-method-does-not-know', 12, 'The barrel each of the two modules returns is 5.6145833333333 cubic feet, at a ratio of 1.0000000000000. What does that agreement rest on, and what does it not establish?', '["The golden oracle supplying the same figure to both modules in SI units, so what the agreement establishes is that the field-unit conversion inside each of the two modules has been applied once and in the right direction.", "One shared definition, forty-two gallons of two hundred and thirty-one cubic inches each over the seventeen hundred and twenty-eight cubic inches in a cubic foot, and a definition is not a measurement.", "The larger of the two modules standing as the reference the smaller is read against, so what the agreement establishes is that lineHydraulics is the half a reader should quote whenever the two modules are being read together.", "The ratio being carried to thirteen decimals before it is compared, so what the agreement establishes is that a barrel reproduces to that precision and leaves open only whatever sits in the digits beyond it."]'::jsonb, 1, 'A definition fixes a conversion and says nothing whatever about a pipeline. What the pair of returns does show is that the erosional chain and the volume chain are counting the same barrel, which is the condition for reading either against the other at all.'),
  ('linesizing', 'advanced', 'module', 'm05-what-the-method-does-not-know', 13, 'What does this engine contain of the multiphase half?', '["The holdup correlation only, which is why a swept volume can be computed at all, while the flow regime and the slug model belong to the Suite app code.", "The slug model only, since the swept volume and the interval a catcher allows are both slug quantities and both are computed inside this engine.", "None of it. There is no flow regime, no slip, no holdup correlation and no slug model anywhere in it.", "The flow regime only, which is reported as the regime word beside the friction factor, while slip and holdup are taken as inputs wherever they are needed."]'::jsonb, 2, 'Two-phase pressure drop, flow regime and holdup are the Suite Beggs and Brill correlation, which is app code. Wherever this engine needs a holdup it takes one as an input.'),
  ('linesizing', 'advanced', 'module', 'm05-what-the-method-does-not-know', 14, 'Why is an absence harder for a reader to notice than a held item?', '["A held item announces itself in writing, and an absence has no field to attach a warning to, so a two-phase line returns a velocity, a Reynolds number, a friction factor and a pressure drop that are all arithmetically correct for a single-phase fluid.", "An absence is refused by the engine in the ordinary way, so a reader sees only an error string and has no figure in front of them to question.", "A held item is graded and an absence is not, so a reader meets the held item in the capstone and never meets the absence at all.", "An absence is recorded in the digest under a different heading from the held items, and a reader working from the lessons alone never reaches that part of the digest."]'::jsonb, 0, 'The engine cannot detect it, because a mixture density is a perfectly ordinary number. Nothing in the answer says the single-phase result is the wrong model rather than an imprecise one.'),
  ('linesizing', 'advanced', 'module', 'm05-what-the-method-does-not-know', 15, 'A report states that the golden suite for this engine is green and describes that as validation of the line sizing method. What has been overstated?', '["Green means every published wall, pigging and friction case reproduces, which says nothing at all about the cases that were never published, so the overstatement is one of coverage rather than one of kind.", "Green means the engine agrees with the oracle to the four decimals the goldens are stated at, and the overstatement is the precision the word validation implies.", "Green means the arithmetic closed on the day the goldens were cut, and since nothing here reads a clock the overstatement is that the result is current.", "Green means the engine agrees with an independent implementation of the same assumptions, and calling that agreement with measured pipeline performance changes the claim entirely."]'::jsonb, 3, 'The goldens arbitrate between implementations and they do not speak for any measured pipeline. Refusing to run them for that reason is the opposite mistake, because arbitration is worth having on its own terms.'),
  ('linesizing', 'advanced', 'module', 'm06-the-expert-reading', 1, 'Three readings close this tier: what a line costs in pressure, what wall a code demands of it, and what it holds. What is the relation between those three answers?', '["The pressure drop sets the other two, since a design pressure follows from the loss along the line and the volume follows from the bore the loss was computed over.", "Not one of them can be derived from the other two, so a reader who knows the pressure drop knows nothing about the wall and a reader who knows the wall knows nothing about the slug.", "The wall sets the other two, since it fixes the internal bore that both the velocity and the line volume are then computed from, once an outside diameter has been stated.", "The volume sets the other two, since bore and length are the only geometry any of the three chains uses and both of the others read that geometry out of it."]'::jsonb, 1, 'A loss of 25.660631 psi, a required wall of 0.419231 in at Class 3 and a line volume of 1633.5349 bbl are three separate results. Each needs inputs the other two never ask for.'),
  ('linesizing', 'advanced', 'module', 'm06-the-expert-reading', 2, 'The OGBIA hydraulic reading and the OGBIA volume reading are two separate answers about one line. What do the two chains actually share?', '["The velocity of 2.244621 ft/s, which the volume chain takes as the speed the sphere is driven along the same 26400.000000 ft at.", "The Reynolds number of 48431.2523, which the volume chain reads to decide whether the bore was running full before it reports 1633.5349 bbl.", "The bore of 7.981000 in and the length of 26400.000000 ft, which is the whole of the overlap between them.", "The density and the viscosity, which the volume chain needs in order to turn the cubic feet of the bore into the 1633.5349 bbl it reports."]'::jsonb, 2, 'A line volume is geometry and nothing else. Everything the hydraulic chain adds, a rate, a density and a viscosity, is absent from the volume and from the run.'),
  ('linesizing', 'advanced', 'module', 'm06-the-expert-reading', 3, 'The wall reading quotes 0.419231 in at Class 3 and 0.329327 in at Class 1 on the SOKU pipe. What are those two figures, and what is the 0.375000 in beside them?', '["They are required walls, the steel somebody orders, and 0.375000 in is the wall the mill actually rolled, which rates back to 1019.607843 psig.", "They are pressure walls, the steel that holds the design pressure of 1200.000000 psig, and 0.375000 in is the corrosion allowance the code adds on top of whichever of the two applies.", "They are the walls at the two ends of the class table, and 0.375000 in is the mean of the four.", "They are the walls before and after the temperature derate, and 0.375000 in is the wall that would be required if the derate on this pipe were 1.000000 rather than the value it carries."]'::jsonb, 0, '0.294231 in and 0.204327 in are the pressure walls on the same two rows. A design wall is a requirement and the rolled wall is a fact.'),
  ('linesizing', 'advanced', 'module', 'm06-the-expert-reading', 4, 'The volume reading returns 1633.5349 bbl held, 2.444444 hours for a crossing and 98.0121 bbl every 3.7997 days. Which of those is pure geometry?', '["The 1633.5349 bbl and the 2.444444 hours both are, since a length over a speed uses no fluid property at all, and only the sweep rests on a number somebody stated.", "All three are, since no density, viscosity or pressure enters any of them, and the holdup of 0.060000 is a property of the bore rather than of the flow inside it.", "Only the 2.444444 hours is, since a volume in barrels rests on the 5.6145833333333 cubic feet per barrel and a conversion factor is a stated number in the same way a holdup is.", "Only the 1633.5349 bbl. The run rests on a stated pig speed and the sweep and the interval rest on a stated holdup."]'::jsonb, 3, 'Bore and length give 1633.5349 bbl and nothing else enters. The speed of 3.000000 ft/s and the holdup of 0.060000 are both handed in from outside.'),
  ('linesizing', 'advanced', 'module', 'm06-the-expert-reading', 5, 'The OGBIA duty runs at 2.244621 ft/s against an erosional ceiling of 13.545709 ft/s and uses 0.165707 of it. What does that fraction settle, and what does it leave open?', '["It settles that the bore could be reduced until the fraction approached 1.000000, and it leaves open only what the pressure drop would become at the higher velocity that followed.", "It settles that the erosional check is the constraint governing this line rather than the friction loss, and it leaves open whether the pressure drop of 25.660631 psi is acceptable over 26400.000000 ft of it.", "It settles that the line is nowhere near its erosional limit, and it leaves open how conservative that limit is, because the c factor behind the ceiling is held for the literature.", "It settles the velocity the sphere will be driven at, since a pig travels at whatever fraction of the erosional ceiling the fluid ahead of it is using, and it leaves open only the holdup the sphere will find."]'::jsonb, 2, 'The three c factors of 100.000000, 125.000000 and 175.000000 are held. An erosional velocity at a stated c factor is a complete answer to a stated question.'),
  ('linesizing', 'advanced', 'module', 'm06-the-expert-reading', 6, 'The tier''s second three modules did not add a new answer about any line. What did they add?', '["They changed what a number means: where the correlations stop, what a refusal is, and what the method does not know.", "They added the audit figures themselves, such as the jump of 1.603040 and the implied friction factors, which are results about the line in the same sense as its pressure drop.", "They added the guards, since a boundary read on both sides is a new answer at each limit.", "They added provenance, which is a fourth reading beside the other three."]'::jsonb, 0, 'A friction factor that jumps 1.603040 times, a Colebrook curve answering outside its fit, four forms that never check their own regime, and two iterations that never report convergence.'),
  ('linesizing', 'advanced', 'module', 'm06-the-expert-reading', 7, 'In the capstone the wall chain has to be run in a particular order. What comes first and what is asked of what?', '["The rating is read first off the wall the mill rolled, and the design pressure that comes back is what the wall is then sized against under the code and the class.", "The pressure wall and the required wall are sized together and the rating is asked of the required wall, since that is the wall the design specified and the one the line is held to.", "The corrosion allowance is applied first to the outside diameter, and the wall is then sized from the reduced geometry so that the rating and the sizing use one pipe.", "The wall is sized from the design pressure, the outside diameter and the yield under a code and a class, and then the rating is asked of the wall the mill actually rolled."]'::jsonb, 3, 'Two numbers come out of the sizing and they are not interchangeable. The design wall is a requirement and the rolled wall is a fact, and the two separate the moment the mill rounds.'),
  ('linesizing', 'advanced', 'module', 'm06-the-expert-reading', 8, 'The volume chain runs bore and length to a volume, volume and holdup to a sweep, length and speed to a run, and sweep against a catcher to an interval. What follows from that shape?', '["Each step needs every step before it, so an error is caught where two inputs fail to reconcile.", "Each step needs only the step before it, so an error early travels the whole way down without ever being contradicted.", "The run time is the only step outside the chain, so an error in the bore reaches the volume, the sweep and the interval but is caught by the run, which reads the length alone.", "The interval closes the chain by returning the holdup it implies, so a bore or a length that was wrong shows up as an implied holdup that does not match the one supplied."]'::jsonb, 1, 'Check the bore and the length before anything else, because both the volume and the run depend on them. Nothing downstream can disagree with a figure it inherited.'),
  ('linesizing', 'advanced', 'module', 'm06-the-expert-reading', 9, 'Four inputs in this tier are stated conditions rather than results and each has to travel beside the figure it produced. Which four?', '["The design pressure, the outside diameter, the specified minimum yield and the corrosion allowance, which are the four arguments Barlow cannot proceed without.", "The c factor, the efficiency, the roughness and the resistance sum, the four held items.", "The location class with its code, whether the allowance was respected in the rating, the holdup, and the pig speed.", "The bore, the length, the dropout rate and the slug limit, which are the four inputs the volume chain needs before it can return an interval."]'::jsonb, 2, 'The wall is meaningless without its class and code, the swept volume is a straight multiplication by the holdup, and the run time is a length divided by the speed.'),
  ('linesizing', 'advanced', 'module', 'm06-the-expert-reading', 10, 'The capstone asks for figures at the precision the engine returned them. What are the conventions?', '["Liquid work to six decimals, with barrels and hours and days all three to four and counts as whole numbers, since the hours come off the same pigging chain the volumes do.", "Everything to six decimals, since that is the precision the wall and the pressure figures are printed at and a single convention avoids a rounding argument.", "Everything to the precision of the least precise input, which for the pigging chain is the holdup of 0.060000 and therefore six decimals throughout.", "Liquid work to six decimals, the run hours among it, with barrels and days to four and counts as whole numbers."]'::jsonb, 3, 'Quote what the engine returned rather than a rounding of it. A run time is liquid work and prints to six decimals, 2.444444 hours on the OGBIA duty, and barrels and days print to four.'),
  ('linesizing', 'advanced', 'module', 'm06-the-expert-reading', 11, 'A step in the capstone chain returns an object carrying an error string. What should be reported for that step?', '["The error itself, because a refusal is a result and writing a number where the engine declined to produce one is the worst available answer.", "The last value the chain produced before the refusal, since the error names the input that was missing and the previous step is the answer the engine did reach.", "A null, since that is what a refusal serialises to and it records that no figure was available without asserting anything about what the figure would have been.", "The figure computed by hand, since the refusal is about the guards rather than about the physics."]'::jsonb, 0, 'If any step returns an object carrying an error, that error is the answer to give. A caller checks a property rather than catching.'),
  ('linesizing', 'advanced', 'module', 'm06-the-expert-reading', 12, 'No graded figure in this course rests on a held item. What makes that claim checkable rather than merely asserted?', '["The held items are excluded from the engine entirely in the graded chains, so a graded figure cannot reach one even if a caller supplies it.", "The c factor, the efficiency, the roughness, the resistance sum, the location class and the holdup are stated conditions wherever they appear, so an answer can be checked against the condition.", "The graded tolerances are set wider than the range a held item could move an answer over, so a held item cannot change whether a graded figure scores.", "Each graded figure is confirmed against the golden oracle, which works in SI and carries no held item at all, so agreement proves the held items played no part."]'::jsonb, 1, 'That turns a held item from a hidden dependency into a stated condition. A reader who wants to check an answer can check it against the condition rather than against an unsourced table.'),
  ('linesizing', 'advanced', 'module', 'm06-the-expert-reading', 13, 'The tier ends with a three-way question to ask of any figure. What is it, and why are the three answers different?', '["Whether it was computed, measured or golden, because only the first of those moves with the duty and the other two are fixed records of a case that has already been run.", "Whether it was computed, held or refused, because the three are the classes of return this engine produces and every figure in the course belongs to exactly one of them.", "Whether it was computed, converged or printed, because an unconverged iterate and a rounded print both look identical to a computed figure once they are written down.", "Whether it was computed, copied or assumed, because a computed figure moves when its duty moves, a copied figure never moves at all, and an assumed figure moves when somebody changes their mind."]'::jsonb, 3, 'A swept volume looks computed and is half assumed. A c factor looks like a standard and is copied. A friction factor from inside the band between 2100 and 4000 came from a correlation not written for it.'),
  ('linesizing', 'advanced', 'module', 'm06-the-expert-reading', 14, 'Four things in this domain live in other engines. Which, and what does each handle?', '["A network solve for lines sharing a header, a live-oil flowline upstream of separation, the vessel that catches a slug, and the whole multiphase half that supplies a holdup.", "A network solve for lines sharing a header, the wall a code demands, the vessel that catches a slug, and the whole multiphase half that supplies a holdup.", "A network solve for lines sharing a header, a live-oil flowline upstream of separation, the erosional ceiling of 13.545709 ft/s, and the friction factor the four gas forms assume.", "A live-oil flowline upstream of separation, the vessel that catches a slug, the transmission efficiency, and the outlet-pressure solve that marches a profile down a hill."]'::jsonb, 0, 'Each of those is a seam rather than a gap. The work exists and is simply not in this chain, and a number crossing one of those seams should be named as having crossed it.'),
  ('linesizing', 'advanced', 'module', 'm06-the-expert-reading', 15, 'The tier closes on one habit. What is it?', '["Recompute every figure at a second duty, since a computed figure moves with its duty and a copied one does not, and the pair distinguishes them.", "Quote every figure to the precision the engine printed it at, since the precision is what records which chain the figure came out of.", "Read what sits beside the number: a regime word, an error string, a stated class, a stated holdup.", "Check every figure against its golden, since an independent implementation in another unit system is the only test available inside this package."]'::jsonb, 2, 'Nearly every trap in this tier is sprung by taking the number and leaving the qualifier behind. The qualifier is the cheaper half to carry and the half that survives review.'),
  ('linesizing', 'advanced', 'final', null, 1, 'A route survey returns Class 2 where the design had assumed Class 1, on the SOKU pipe at 1200.000000 psig. What happens to the wall?', '["The design factor falls from 0.720000 to 0.600000, so the pressure wall thickens from 0.204327 in to 0.245192 in and the required wall from 0.329327 in to 0.370192 in.", "The design factor falls from 0.720000 to 0.500000, so the pressure wall thickens from 0.204327 in to 0.294231 in, since Class 2 is the second entry down the B31.8 table.", "The design pressure rises above 1200.000000 psig to reflect the populated route, and the wall thickens in proportion to that rise while the factor of 0.720000 stands.", "Nothing happens to the wall, because B31.4 uses a flat 0.720000 whatever the route, and a line already rolled to that factor is legal on any location class."]'::jsonb, 0, 'Class 2 is the second row of the B31.8 table, at a factor of 0.600000. Every row of that table carries the same 0.125000 in between its pressure wall and its required wall.'),
  ('linesizing', 'advanced', 'final', null, 2, 'A wall call with no design pressure and a wall call to a code named B99 are two different failures. What do they have in common, and where do they differ?', '["Both throw, because a missing argument and an unknown code are the two cases in this engine that leave the ordinary path, and they differ only in the text of the message.", "Both come back as a bare NaN, because the wall is a single number with nowhere to attach a message, and they differ in that only the unknown code is reported by the wrapping function.", "Both come back as an object carrying an error string through the ordinary return path, and one names three inputs Barlow cannot proceed without while the other names the code it does not carry.", "Both come back as an object carrying an error string, and they differ in that the missing design pressure is a physically meaningless input while the unknown code is a state the method simply has no answer for."]'::jsonb, 2, 'This engine throws nothing. The first says wall thickness needs positive design pressure, OD and SMYS, and the second names the design code it does not know.'),
  ('linesizing', 'advanced', 'final', null, 3, 'On the SOKU pipe at Class 1 the pressure wall is 0.235671 in at a temperature derate of 0.867000 and 0.211300 in at 0.967000. What does that pair establish about the derate?', '["That it multiplies the design pressure, so a derate of 0.867000 asks the wall to hold a lower pressure than 1200.000000 psig and a thinner wall follows from it.", "That it divides, so the wall thickens as it falls, which is the same behaviour the joint factor and the design factor show.", "That it is a measured property of the delivered steel, recorded alongside the yield of 52000.000000 psi, which is why two values of it give two different walls on one pipe.", "That it is added to the wall after Barlow has produced it, in the same way the corrosion allowance of 0.125000 in is added, which is why the two walls differ by a fixed amount."]'::jsonb, 1, '0.867000 gives the thicker of the two walls. The joint factor column behaves the same way, running from 0.340545 in at 0.600000 to 0.204327 in at 1.000000.'),
  ('linesizing', 'advanced', 'final', null, 4, 'A capstone answer gives a wall figure with no class and no code beside it. Why is that answer incomplete even if the arithmetic is right?', '["The engine refuses a wall call that has no class, so a figure produced without one cannot have come from the engine and must have been computed by hand.", "A wall with no class stated defaults to Class 1 at a factor of 0.720000, which is legal only where the route survey has already returned an empty classification.", "The corrosion allowance is set by the class, so without the class a reader cannot tell how much of the required wall is pressure-carrying steel.", "The design factor comes from the code and the class rather than from the pipe, so a wall with no class named is a number nobody can check or reproduce."]'::jsonb, 3, 'The same pipe at the same pressure needs 0.204327 in at Class 1 and 0.367788 in at Class 4. The location class and the code are stated conditions that have to travel with the answer.'),
  ('linesizing', 'advanced', 'final', null, 5, 'The four published wall cases each agree with a golden to ten decimal places. What kind of agreement is that?', '["Agreement with an independent implementation of the same physics in another unit system, which catches an arithmetic or a unit error and cannot catch a method wrong in both files.", "Agreement with a measured wall taken off a pipe in service, which is the strongest evidence a wall calculation can carry and is why these four cases were chosen for the course.", "Agreement between the sizing direction and the rating direction, which is the round trip closing and is the only check that can ever be made on a code factor.", "Agreement with the published B31.8 tables themselves, which is what a golden for a code calculation has to be cut against if it is to say anything at all about the code."]'::jsonb, 0, 'The four walls are 0.2451923077 in, 0.2051091270 in, 0.2053571429 in and 0.2261707785 in, and each golden reproduces its engine figure. No measured pipeline is in this course.'),
  ('linesizing', 'advanced', 'final', null, 6, 'A rating is taken on 0.375000 in of wall at Class 3 with the corrosion allowance left out of the call, and 1529.411765 psig is quoted as the MAOP. Which of the engine''s defences would have caught that?', '["The corrosion allowance guard, which refuses a negative allowance, would have caught it if the call had passed 0.000000 in rather than omitting the argument entirely.", "The round trip, which would have failed to return the 1200.000000 psig the line was designed at and thereby flagged the inconsistency between the two directions.", "None of them, because every input was meaningful and fully formed, so the wrong question was asked correctly and no guard can see that.", "The refusal contract, since a rating with no wall left after the allowance returns an error object and the same check covers a rating with no allowance at all."]'::jsonb, 2, 'Both calls are legal, both are correct for what they were asked, and neither warns. The factor of 1.500000 between them is the gross wall over the net.'),
  ('linesizing', 'advanced', 'final', null, 7, 'Three published pigging runs return line volumes of 33.2033 bbl, 1071.9949 bbl and 5149.6679 bbl. What entered those three figures?', '["A bore, a length and the holdup of each run, since a line volume is reported at the conditions the line was carrying when the sphere was launched into it.", "A bore, a length and a density, since barrels are a measure of mass in this engine and the 5.6145833333333 cubic feet per barrel converts between the two.", "A bore, a length and a pig speed, since the three runs are all driven at 5.000000 ft/s and the volume is what the sphere sweeps over the time it is in the line.", "A bore and a length in each case and nothing else, because a line volume is geometry and no fluid property reaches it."]'::jsonb, 3, 'A line full of crude, a line full of gas and a line full of seawater are the same volume. The holdup enters one step later and turns a volume into a sweep.'),
  ('linesizing', 'advanced', 'final', null, 8, 'Why does this engine take a holdup as an input rather than computing one?', '["Because a holdup measured in the field is more reliable than one correlated, so the engine deliberately declines to compute a figure that an operator can supply.", "Because the multiphase half is not in it at all: no flow regime, no slip, no holdup correlation and no slug model, so the number has to come from outside.", "Because the holdup depends on the swept volume, which the engine has not computed at the point where the holdup is needed, so the dependency runs the wrong way to close.", "Because the Beggs and Brill correlation inside this engine returns a holdup only for inclined lines, and a horizontal line has to be handed one instead."]'::jsonb, 1, 'The swept volume is a line volume times a figure somebody else measured or assumed, so a pigging estimate is only as honest as that figure and nothing records where it came from.'),
  ('linesizing', 'advanced', 'final', null, 9, 'On the OGBIA line the sweep at a holdup of 0.040000 is 65.3414 bbl and at 0.060000 it is 98.0121 bbl, and the intervals are 4.6165 days and 3.7997 days. Why does a rise of 0.020000 in holdup cost less than a day?', '["Because the interval falls as the square root of the sweep, so equal steps in holdup cost progressively less as the sweep grows towards the catcher limit.", "Because the engine holds the interval above a floor until the sweep exceeds the slug limit, at which point it stops reporting days at all rather than approaching zero.", "Because the interval is the room left in the catcher over the dropout, and a sweep of 32.6707 bbl more takes that much room out of 250.000000 bbl at 40.000000 bpd.", "Because the dropout of 40.000000 bpd falls as the holdup rises, so part of the room the sweep takes is returned by the slower accumulation behind it."]'::jsonb, 2, 'The relation is linear in the room taken. The column runs 6.2500, 5.4332, 4.6165, 3.7997 and 2.1662 days before the engine refuses.'),
  ('linesizing', 'advanced', 'final', null, 10, 'A designer meets the slug-limit refusal at a holdup of 0.200000 and proposes a third response: keep the interval and accept a thinner margin on the catcher. Why is that response not available on this row?', '["There is no margin left to thin: the sweep of 326.7070 bbl is larger than the whole 250.000000 bbl the vessel holds, so the catcher is over its limit before a single day of dropout is counted.", "The engine has already taken a margin off the slug limit before comparing it against the sweep, so the figure a caller supplies is not the one the refusal was raised against.", "A thinner margin would return a negative interval, which the engine reports as a number rather than refusing, so the designer would be acting on a figure that cannot be scheduled.", "The slug limit belongs to the separation work rather than to this chain, so it is the one input a caller of this engine is not permitted to move."]'::jsonb, 0, 'The message names the only two levers there are, pig more often or resize the catcher. At a holdup of 0.100000 the same line still reports 2.1662 days, and the room the sweep leaves is what the dropout fills.'),
  ('linesizing', 'advanced', 'final', null, 11, 'The holdup guard and the swept volume guard are both read on two sides. Which values does the engine accept, and what does accepting them say?', '["A holdup just below 1.000000 and a sweep just above 0.000000, refusing the two limits themselves, since a full line and a dry line are degenerate cases the engine declines.", "A holdup of 1.000000 and a swept volume of 0.000000, refusing 1.000001 and -0.000001, and accepting them says the engine recommends designing at those two conditions.", "A holdup of 1.000001 and a swept volume of -0.000001, since the guards are written with strict comparisons and admit the first step past their own stated limits.", "A holdup of 1.000000 and a swept volume of 0.000000, refusing 1.000001 and -0.000001, and accepting them says a liquid-full line and a dry line are real conditions to ask about."]'::jsonb, 3, 'Each guard includes its own limit and refuses the first step past it. Accepting the question is not advice to design for it.'),
  ('linesizing', 'advanced', 'final', null, 12, 'A pigging plan quotes a run of 2.444444 hours and the 3.000000 ft/s the sphere was driven at, and nothing else. What has been left out, and why does it matter?', '["Nothing of substance, since the run and the speed the engine reports beside it are the two figures any pigging operation is scheduled from in practice.", "The sweep and the interval, because the run says when the sphere arrives and the sweep says what arrives with it and the interval says how often.", "The line velocity of 2.244621 ft/s, because a sphere is pushed by the fluid behind it and the two speeds have to be compared before a run time is credible.", "The Reynolds number of 48431.2523, because a run is valid only where the flow behind the sphere is turbulent."]'::jsonb, 1, 'A pigging plan needs all three. The run is 26400.000000 ft over 3.000000 ft/s, the sweep is 98.0121 bbl at a holdup of 0.060000, and the interval is 3.7997 days.'),
  ('linesizing', 'advanced', 'final', null, 13, 'A line''s duty puts its Reynolds number close to 2100, and the loss the engine reports jumps when the duty is nudged. What is the engineering response?', '["Interpolate between the two branches at the duty in question, since the engine will return a value on each side and the truth lies somewhere between the pair.", "Quote the transitional friction factor at the ten decimals the engine prints, since those digits record which of the two branches actually produced the number.", "Move the bore or the rate until the flow is clearly laminar or clearly turbulent, which is a real fix rather than a presentational one.", "Take the laminar value of 0.0304761905, since it is the lower of the two and a line sized on the smaller loss carries margin against the larger one."]'::jsonb, 2, 'A pressure drop that depends on which side of an arbitrary boundary a Reynolds number lands on is not a design. The step across that boundary is 1.603040 times.'),
  ('linesizing', 'advanced', 'final', null, 14, 'Inside the band from 2100 to 4000 the engine hands back a regime word and a friction factor together. What should a reader do with that pair?', '["Carry both and record that they disagree, since the label and the arithmetic in that band rest on different assumptions and nothing in the return marks it.", "Take the friction factor and discard the word, since the arithmetic is what the pressure drop needs and the label carries no information the number does not.", "Take the regime word and discard the friction factor, since a value computed on a branch other than the one it is labelled for is not a quantity any design should carry forward.", "Take neither, since the engine refuses to return a friction factor in the band and the pair a caller sees is the refusal object rather than a result."]'::jsonb, 0, 'The regime word is not wrong and the friction factor is not a fabrication. The band is held for the literature and never graded.'),
  ('linesizing', 'advanced', 'final', null, 15, 'A line is partly blocked by wax and a designer raises its relative roughness to 0.500000 to stand for the blockage, taking the 0.3308894263 that comes back. What is wrong with that, beyond the extrapolation?', '["Nothing is wrong with the substitution itself and only the extrapolation is at fault, so the same approach is sound on any line wherever the value stays under the published 0.050000.", "It is the wrong sign of correction, since a partly blocked bore lowers the loss a line reports and raising the roughness raises it, so the two effects work against each other.", "The engine will refuse the run, because a relative roughness of 0.500000 describes a wall rougher than the bore is wide and the roughness guard is written to catch exactly that.", "Wax changes the flow area and the geometry, so a real effect has been pushed into a term nobody fitted for it while the bore the whole chain computes over is still the clean one."]'::jsonb, 3, 'Scale, wax and a partially blocked bore change the flow area. The engine answers 0.3308894263 and flags nothing, because the value is meaningful even where nobody fitted it.'),
  ('linesizing', 'advanced', 'final', null, 16, 'On the 11.938000 in bore General Flow settles on 0.0112132010 and the figure that would make it match Weymouth is 0.0139989737. What may a designer do with that pair?', '["Enter 0.0139989737 as the roughness-derived friction factor in a General Flow run, so that the two forms are brought into agreement on this bore before either rate is quoted.", "State that Weymouth is assuming a rougher pipe than Colebrook computes here, and stop there, because nothing sources the law behind the implied figure.", "Adjust the transmission efficiency until the two rates close on this bore, since a gap of that size is exactly the correction the multiplier exists to make.", "Quote 0.0139989737 as the friction factor of the line, since it came out of a form with no roughness input to get wrong."]'::jsonb, 1, 'The implied figure is above the computed one on all four bores and falls as the bore grows, which is the signature of a fully rough law. The law itself is held for the literature.'),
  ('linesizing', 'advanced', 'final', null, 17, 'A designer picks Panhandle B because it gives the most favourable rate on a line and defends the choice by pointing out that the arithmetic is correct. What is wrong with that defence?', '["All four forms are arithmetically correct, so correctness cannot choose between them, and the choice is an engineering judgement about which assumptions fit the line.", "Panhandle B is the only one of the four that carries no efficiency multiplier, so its rate cannot be compared against the other three without one being applied first.", "The arithmetic is not correct, since no form checks its own regime and a form applied outside the flow it was derived for returns a number that is wrong rather than inapplicable.", "Panhandle B reports no friction factor, so there is no way to establish that its arithmetic is correct in the first place and the defence cannot be made at all."]'::jsonb, 0, 'Each form was derived for a kind of line under a kind of flow and not one checks whether it was handed that kind of line. The judgement has to be made and recorded as a judgement.'),
  ('linesizing', 'advanced', 'final', null, 18, 'Two loops in this module return their last iterate with no flag. The outlet-pressure solve handles a case it cannot answer differently. What is the difference?', '["The outlet solve reports the number of iterations it ran, so a caller can see whether it converged, and the two loops report neither a count nor a residual.", "The outlet solve returns the bracket it searched beside its answer, so a caller can see the interval the outlet was found in, and the two loops return no interval at all.", "The outlet solve refuses in words when the line cannot carry the target rate, so it distinguishes an answer from the place it stopped, and the two loops have no such distinction available.", "The outlet solve returns a NaN when it cannot answer, which a caller can test for, and the two loops return a plausible number that no test can distinguish."]'::jsonb, 2, 'Both loops converge everywhere this digest looked. What is absent is the evidence, and a second run cannot supply it because nothing here reads a clock or a random number.'),
  ('linesizing', 'advanced', 'final', null, 19, 'What is the contract every refusal in this engine keeps to, and why is the shape the useful part?', '["A thrown exception carrying a sentence, which leaves the normal path so that no caller anywhere can read past a failure by accident, and which a single handler at the top of the chain can catch.", "A null in the field the answer would have occupied, which is unambiguous because no valid result anywhere in this engine is ever null, so one test in one place covers every failure it has.", "A documented sentinel, a negative value in a field that is otherwise positive, which is cheap to test for and cannot be produced by any legitimate calculation.", "An object carrying an error string, arriving where the answer would have arrived, which cannot be confused with a pressure or a rate and carries a sentence naming what was missing."]'::jsonb, 3, 'A thrown exception can unwind past the code that knew what to do. A sentinel is indistinguishable from a real answer that happens to equal it. A null says nothing about what went wrong.'),
  ('linesizing', 'advanced', 'final', null, 20, 'A capstone answer reports a swept volume as null because the call behind it was refused. Why is that the wrong thing to write?', '["A null is exactly what a refusal serialises to, so the form is right and the only thing lost is the message, which can be recovered by running the call again.", "A refusal is a result, so the error string is the answer to give, and a null cannot say which guard or which documented exception produced it.", "A null belongs to the friction factor at a negative relative roughness, so writing one anywhere else collides with a value the engine sets deliberately.", "A swept volume of 0.000000 bbl is the correct answer when an input is missing, since the engine accepts that value and a dry line really does deliver nothing."]'::jsonb, 1, 'Writing a number where the engine declined to produce one is the worst available answer. A NaN has no JSON spelling either, so a null in a record cannot be traced back to what produced it.'),
  ('linesizing', 'advanced', 'final', null, 21, 'Three returns sit outside the refusal contract. What does each one return, and what is the pattern behind all three?', '["NaN in all three, every one of them a bare number, the pattern being that a bare number is the only return a function can make when the failure happens before any object has been assembled to carry a message.", "An error object for all three, the pattern being that they sit outside the contract in the sense that they are reached from outside the ordinary entry points rather than in their shape.", "NaN in all three, bare for a Reynolds number with no viscosity and for a volume with no bore and beside a regime of invalid for the friction factor, the pattern being that a function refuses in words only where it has room for a message.", "A null for the two bare numbers and NaN for the friction factor, the pattern being that a value with a field beside it can hold a null while a value on its own cannot."]'::jsonb, 2, 'Neither of the two bare numbers is reached through the ordinary entry points, so the exception is contained by the design rather than by a convention somebody has to remember.'),
  ('linesizing', 'advanced', 'final', null, 22, 'A saved case file from this engine contains a null where a friction factor should be. What can be concluded?', '["Less than it looks: a NaN has no JSON spelling and prints as null, so the record cannot say whether the engine returned NaN or set a field to null on purpose.", "That the friction factor call was refused at a negative relative roughness, since that is the one case in this engine that genuinely sets a friction factor to null.", "That the encoder replaced a value it could not represent, which means the original figure is recoverable from the inputs by running the call again.", "That the engine threw and the caller wrote a null in place of the missing result, since a refusal in this engine never reaches a saved file as a value."]'::jsonb, 0, 'All three exceptions are a number that is not a number, and not one of them is a null the engine chose. The regime field is the only thing that distinguishes the third.'),
  ('linesizing', 'advanced', 'final', null, 23, 'Six sentences in the meaningless-input catalogue appear twice. Which pair below is one sentence reached from two different entry points?', '["The efficiency message, which answers a gas form for a multiplier above one and a liquid line for the same multiplier below zero.", "The swept volume message about a positive bore and length, which answers a sweep call and the interval call that follows it.", "The gas length message, which answers a transmission form and the elevation adjustment that feeds a value into it.", "The elevation message, which answers a liquid line that rises further than its own length and a gas line that does the same."]'::jsonb, 3, 'Three sentences serve two entry points each: roughness across a liquid friction call and a General Flow call, elevation across a liquid line and a gas line, and the corrosion allowance across a wall call and a rating call.'),
  ('linesizing', 'advanced', 'final', null, 24, 'A reviewer tests the efficiency guard by passing an obviously absurd value and reports that the guard works. What is missing from that test?', '["Whether the guard fires before or after the rate is formed, because an absurd efficiency that reached the form first would have produced a rate on the way to being refused.", "Whether 1.000000 itself survives, because a guard that refuses its own limit is as wrong as one that accepts nonsense and is harder to notice.", "Whether the same guard covers the negative side, because efficiency is refused above one and below zero by two different sentences that have to be tested separately.", "Whether the value was passed to all four transmission forms, because the guard sits on General Flow alone and the other three carry no bound on the multiplier."]'::jsonb, 1, 'An absurd value proves nothing that passing 1.000001 does not prove better. The engine answers at 1.000000 and refuses at 1.000001, which is where the boundary actually is.'),
  ('linesizing', 'advanced', 'final', null, 25, 'Four of the five catalogues answer an unknown id with an absence and one answers with a row. How would a caller detect the odd one out?', '["By comparing the id that came back against the id that went in, because the returned object is correctly labelled continuous service and the label is what reveals the substitution.", "By testing the c factor against 100.000000, because a substituted row always carries that value and a genuine continuous-service lookup never does.", "By checking for an error property, because the substituted row is the only one of the five returns that carries one and the four absences do not.", "By serialising the return, because a genuine row prints as an object and a substituted one prints as null in the way the two bare NaN cases do."]'::jsonb, 0, 'The object is internally consistent and it is not a corrupted row. What it is not is the service that was asked for, and four of the five lookups make that check unnecessary.'),
  ('linesizing', 'advanced', 'final', null, 26, 'What does it mean in this course to say that a figure is held for the literature?', '["That the figure is suspect and is carried only until a correct value can be derived, at which point it will be replaced and the affected results re-cut.", "That the figure is bounded by the engine but not computed by it, so a caller may supply any value inside the bound and the course declines to recommend one.", "That nobody in this package has read a source for it, so it is taught as a limit and never as an answer, and nothing graded rests on it.", "That the figure comes from a table another engine owns, so this course records what it is handed and cannot change what an unknown entry in that table returns."]'::jsonb, 2, 'A held item is not a wrong number. What is missing is the reading that would let anybody say how conservative it is.'),
  ('linesizing', 'advanced', 'final', null, 27, 'Of the three API RP 14E c factors, one is weaker than the other two. Which, and why?', '["100.000000 for continuous service, which the recommended practice does not itself carry and which this package supplied to fill the gap in the table.", "175.000000 for clean inhibited service, which is labelled operator practice with no publication behind it at all.", "125.000000 for intermittent service, which sits between the other two and was interpolated rather than published, so no source exists for it in principle.", "175.000000 for clean inhibited service, which exceeds the bound the engine places on a c factor and is accepted only because the guard was never applied to that table."]'::jsonb, 1, 'The recommended practice says its own figures are conservative, and the third row is labelled operator practice. All three are held, and one is held for a second reason.'),
  ('linesizing', 'advanced', 'final', null, 28, 'Two of the four held items are about friction. Which two, and what separates them?', '["The Colebrook roughness divisor and the laminar numerator, which are both coefficients the engine carries and neither of which has been read against a publication.", "The relative roughness of the OGBIA pipe and the friction factor General Flow settles on, both of which are derived from figures nobody in this package has sourced.", "The transmission efficiency and the API RP 14E c factors, both of which move a computed friction loss by a stated proportion on every line they touch.", "The band between the branches, where no correlation exists at all, and the fully rough law Weymouth assumes, which does exist and has no source in this package."]'::jsonb, 3, 'The four are the c factors, the efficiency multiplier, the band from 2100 to 4000 and the law Weymouth assumes. The step across that band is 1.603040 times.'),
  ('linesizing', 'advanced', 'final', null, 29, 'A report says the goldens behind this course are green and concludes that the engine is validated against pipeline performance. Where does that go wrong?', '["The goldens are synthetic, produced by an independent oracle from the same physics, so green means agreement about arithmetic rather than agreement with any measured line.", "The goldens are green only on the published cases, so the conclusion overstates the coverage rather than the kind of evidence, and it would hold if every case had been swept.", "The goldens are cut from the engine itself, so agreement is guaranteed by construction and the suite establishes nothing whatever about the engine''s behaviour.", "The goldens work in SI where the engine works in field units, so agreement between them is evidence about the conversions alone and cannot detect an arithmetic slip in either file."]'::jsonb, 0, 'Arbitration between two implementations is the job a synthetic case does well. It is not a claim about any pipeline.'),
  ('linesizing', 'advanced', 'final', null, 30, 'A barrel is measured out of lineHydraulics and out of chokePerformance by asking each module a question about itself. Why is that a better reading than opening either source file?', '["A source file carries the constant in SI where the modules work in field units, so reading one would require a conversion that the measurement avoids making.", "A source file is not vendored with the goldens, so the constant it carries cannot be reproduced by anybody reading this course from the package alone.", "A source file says what somebody typed and a question put to the module says what the module returns, which is the figure every result in that module was actually computed with.", "A source file states the constant to fewer digits than the modules return it at, so reading one would lose precision that the erosional and volume chains both need."]'::jsonb, 2, 'A source file records an intention and a return records a behaviour. Every barrel the volume chain and the erosional chain have ever produced was produced with the figure the question gets back, whatever any file says.'),
  ('linesizing', 'advanced', 'final', null, 31, 'A designer writes that a two-phase line was checked against this engine and passed. What is wrong with that sentence?', '["It is right for the pressure drop and wrong for the wall, since only the liquid chain takes a density and the wall chain would have refused the call outright.", "It is right as written, since the engine takes a holdup as an input and any line that supplies one has thereby declared itself two-phase to the engine.", "It is wrong, and a guard on the holdup catches it, since a two-phase line is exactly the case that supplies a holdup outside the range the sweep will accept.", "Nothing in the engine could have failed the line, because a mixture density is an ordinary number and no guard can be written for physics the module does not contain."]'::jsonb, 3, 'A guard catches malformed input and a mixture density is perfectly well formed. The module carries no flow regime and no slug model that could have disagreed with the line it was handed.'),
  ('linesizing', 'advanced', 'final', null, 32, 'A reviewer has the pressure drop for a line and asks for its wall and its slug on that basis. What is the answer?', '["Neither can be reached from a pressure drop, because the three readings share a geometry and nothing else, and each needs inputs the other two never ask for.", "The wall can be reached, since the pressure drop gives the operating pressure the wall must hold, but the slug cannot without a holdup.", "The slug can be reached, since the pressure drop fixes the bore and the length, and the wall cannot without a location class.", "Both can be reached once the design pressure is stated, since the pressure drop then gives the operating pressure and the bore gives the volume."]'::jsonb, 0, 'A pressure drop needs a rate, a density and a viscosity. A wall needs a yield, a code and a class. A slug needs a holdup. None of those three sets contains the others.'),
  ('linesizing', 'advanced', 'final', null, 33, 'Two figures come out of a wall sizing and only one of them is steel holding pressure. Which figure does an answer hand over for each purpose?', '["The required wall for both, since it is the wall the design specified and the pressure wall is an intermediate the engine reports only for information.", "The pressure wall when the question is how much steel is structural, and the required wall when the question is what to order from the mill.", "The pressure wall for both, since the corrosion allowance holds no pressure at all and any figure including it overstates the pipe from the first day.", "The rating for both, since it is the only one of the three figures that describes the pipe as built rather than the pipe as it was designed."]'::jsonb, 1, 'On SOKU at Class 3 the two are 0.294231 in and 0.419231 in, separated by 0.125000 in of metal that holds nothing on the day the line is commissioned.'),
  ('linesizing', 'advanced', 'final', null, 34, 'The volume chain runs in one direction and nothing downstream can contradict a figure it inherited. What follows for the way a capstone answer is checked?', '["The interval is checked first, because it is the last figure in the chain and an error anywhere upstream shows up in it before it shows up anywhere else.", "The holdup is checked first, because it is the only input from outside the engine and every figure in the chain is a multiple of it.", "The bore and the length are checked first, because the volume and the run both depend on them and an error there reaches every figure after it.", "Each step is checked against its own golden, because the chain offers no internal consistency check and the published cases are the only test available."]'::jsonb, 2, 'Bore and length give the volume, the volume and a holdup give the sweep, length and a speed give the run, and the sweep against a catcher gives the interval.'),
  ('linesizing', 'advanced', 'final', null, 35, 'A swept volume of 98.0121 bbl is quoted in a report with no other figure beside it. What has to be added before anybody can act on it?', '["The run time of 2.444444 hours, because the sweep arrives with the sphere and a slug with no arrival time attached to it cannot be scheduled by anyone.", "The Reynolds number of 48431.2523, because a sweep counts only where the flow ran turbulent.", "The pressure drop of 25.660631 psi, because the sweep depends on what drives the sphere.", "The holdup of 0.060000 it was multiplied by, because the sweep is a straight multiplication and that figure came from outside this engine."]'::jsonb, 3, 'A catcher specified from 98.0121 bbl has been specified from somebody''s estimate. Four inputs in this tier are stated conditions rather than results and this is one of them.'),
  ('linesizing', 'advanced', 'final', null, 36, 'At what precision should an Expert answer report a swept volume and a pressure loss?', '["The swept volume to four decimals and the pressure loss to six, which is what the engine returned in each case.", "Both to six decimals, since that is the finest precision the engine prints and reporting at one convention avoids an argument about rounding.", "Both to four decimals, since a barrel figure cannot be resolved beyond that and a pressure quoted finer would imply a precision the input never had.", "The swept volume to six decimals and the pressure loss to four, since the volume chain carries the holdup and needs the extra digits to reproduce."]'::jsonb, 0, 'A sweep of 98.0121 bbl and a loss of 25.660631 psi are each printed at the convention its own chain uses, and counts are whole numbers.'),
  ('linesizing', 'advanced', 'final', null, 37, 'Three figures in this tier are a c factor of 100.000000, a holdup of 0.060000 and a loss of 25.660631 psi. Where did each of them come from?', '["All three were computed, since each one is returned by the engine and a returned figure is the output of a calculation whatever its own inputs happened to be.", "The c factor was computed from the erosional velocity, the holdup was measured on the line itself, and the loss was copied from one of the published friction cases.", "The c factor was copied from a table, the holdup was assumed by somebody outside this engine, and the loss was computed from the duty.", "The c factor was assumed, the holdup was copied from a published run, and the loss was computed, since the c factor is the one item with no publication behind it."]'::jsonb, 2, 'A copied figure never moves, because it was never a function of anything. A loss moves when the duty moves, and an assumed figure moves when somebody changes their mind.'),
  ('linesizing', 'advanced', 'final', null, 38, 'A friction factor from inside the band between 2100 and 4000 is handed to a reviewer alongside one at 48431.2523. What should be said about the pair?', '["The first is the more reliable of the two, since a lower Reynolds number puts the flow closer to the laminar branch where the friction law is exact.", "The second came from a correlation applied where it belongs and the first came from one that was not written for the band between the branches.", "Both are equally sound, since the engine reports the regime beside each of them and a reader who carries the word has everything needed to use either.", "The first cannot be quoted at all, since the engine refuses to return a friction factor between 2100 and 4000 and any figure there was computed by hand."]'::jsonb, 1, 'The band from 2100 to 4000 is held for the literature, so a figure taken from inside it is a limit to state rather than an answer to quote. 48431.2523 sits well clear of it.'),
  ('linesizing', 'advanced', 'final', null, 39, 'The wall chain and the volume chain both start from a pipe. What do they actually share?', '["Almost nothing: the volume chain needs a bore and a length, and the wall chain needs an outside diameter, a yield, a code and a class.", "The bore, since the wall is taken off the outside diameter to give the bore that the volume is then computed over in the same call.", "The design pressure, since the wall is sized to it and the line volume is reported at the conditions that pressure implies.", "The corrosion allowance, since it thickens the required wall and thins the bore the volume is taken over, so one figure appears in both chains with opposite signs."]'::jsonb, 0, 'Not one of the three Expert readings can be derived from the other two. Each needs inputs the others never ask for.'),
  ('linesizing', 'advanced', 'final', null, 40, 'Section 16 closes on two things the engine still accepts and arguably should not. What are they, and what does this course grade on either of them?', '["Colebrook answering past the roughness it was fitted for and the band between the branches, both of which are graded through the friction factor a sizing sweep uses.", "The two iterations that never report convergence and the three returns outside the refusal contract, both of which are graded through the gas rates that depend on them.", "A liquid holdup of 1.000000 and a swept volume of 0.000000, both of which are graded through the pigging chain that accepts them as legal conditions.", "The catalogue that answers an unknown service under the wrong label and the rating called without its allowance, and nothing graded in this course rests on either of the two."]'::jsonb, 3, 'Neither is a number this course grades. One is a well-formed question answered under a label that was not asked for, and the other is a well-formed question that was the wrong question.'),
  ('linesizing', 'advanced', 'final', null, 41, 'A wall round trip closes on nine cases and two gas forms agree to within 0.050011 on one duty. What do those two facts have in common?', '["Both are checks the engine performs on itself and reports, so both are evidence that the guards in this module are correctly placed on both of their sides.", "Both establish that the two directions of a relation are consistent, which is the strongest evidence available inside a package with no measured data in it.", "Both are statements about arithmetic that say nothing about whether the method fits the line, and both are easy to read as confirmation that it does.", "Both depend on a held item, the design factor in one case and the efficiency in the other."]'::jsonb, 2, 'A round trip cannot reach a question about whether the code factor suits the route. Two forms agreeing on one duty is a fact about those forms at that duty, and the pair moves to 0.105013 at full duty.'),
  ('linesizing', 'advanced', 'final', null, 42, 'A designer wants to write, on the strength of a green golden suite, that the line sizing in this studio has been validated. What is the defensible sentence?', '["That the engine reproduces measured pipeline performance on the published cases, which is what an independent implementation in SI units establishes.", "That the engine agrees with an independent implementation of the same assumptions, written in another unit system, across every published case.", "That the engine has been validated within the limits of the four held items, which are the only part of the package the goldens cannot reach.", "That the engine converges on every published case, which is what agreement between two implementations of the same implicit relations demonstrates."]'::jsonb, 1, 'Agreement between two implementations is evidence about arithmetic and about nothing else. A defensible sentence names the implementation, the assumptions and the unit system, and stops short of the word pipeline.');
